	-- Fonts
	["Fonts"] = "字体", -- draft
	["One font per role: interface text, chat and numbers, titles, damage numbers; plus size and outline."] = "每种用途一种字体：界面文字、聊天和数字、标题、伤害数字；另加大小和描边。", -- draft
	["One font for all of Azeroth. Pick it, scale it, outline it."] = "一款字体贯穿整个艾泽拉斯。挑选、缩放、描边。", -- draft
	["Font Style"] = "字体风格", -- draft
	["A preset that sets every font and text size at once. Change any font afterwards and the style shows Custom.\nFredoka: MelloUI's own round letters, made to fit its icons. The default.\nScriptorium: Carved capitals over a warm book face.\nChronicle: Small capitals over the most readable book face.\nOld Tome: Aged print, like an old book.\nWarband: Bold blackletter: the boldest look.\nClarity: Plain letters: the easiest to read at small sizes.\nGothic: Gothic titles over a book face."] = "一次设置所有字体和字号的预设。之后更改任一字体，样式会显示为自定义。\nFredoka：MelloUI 自己的圆润字母，配合它的图标。默认。\nScriptorium：雕刻风大写字母配温暖的书籍字体。\nChronicle：小型大写字母配最易读的书籍字体。\nOld Tome：陈旧的印刷体，像一本古书。\nWarband：粗黑哥特体：最醒目的外观。\nClarity：简洁字母：小字号时最易读。\nGothic：哥特标题配书籍字体。", -- draft
	["preset: changes every font at once"] = "预设：一次改变所有字体", -- draft
