	["Detach From Portrait"] = "从头像分离", -- draft
	["Gives the reminder button a place of its own, so it no longer follows your player frame. Move it in Edit Layout."] = "让提醒按钮拥有自己的位置，不再跟随玩家框体。在“编辑布局”中移动它。", -- draft
	["Glow"] = "光晕", -- draft
