	["Most Widgets Shown"] = "最多显示小部件", -- draft
	["How many widgets show at once; the rest wait in a \"+ more\" row. Loot rolls, summons and ready checks always show."] = "同时显示多少个小部件；其余在“+ 更多”行中等待。拾取掷骰、召唤和就位确认总会显示。", -- draft
	-- Restock
	["Restock"] = "补货", -- draft
	["Keeps food, drink, ammo and reagents stocked: a reminder when low, and a shopping list at merchants."] = "保持食物、饮料、弹药和材料的库存：不足时提醒，在商人处给出购物清单。", -- draft
	["Water, bread and arrows, topped up before they run out."] = "水、面包和箭，用完之前补满。", -- draft
	["Remind Below"] = "低于此值提醒", -- draft
	["Reminds you when an item drops below this share of its amount."] = "物品低于其数量的这一比例时提醒你。", -- draft
	["Shopping List At The Shop"] = "商店购物清单", -- draft
	["At a merchant, a shopping list of what you are low on. Nothing is bought until you click Buy."] = "在商人处列出你缺少的物品。点击“购买”前不会买任何东西。", -- draft
	["Restock List"] = "补货列表", -- draft
	["What to keep in your bags, and how many. Each character has its own list. /restock opens it too."] = "背包中要保留什么、多少。每个角色有自己的清单。/restock 也可打开。", -- draft
	["Edit"] = "编辑", -- draft
