	-- Discard
	["Discard"] = "丢弃", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "背包和拾取窗口上的一个按钮，丢掉你最便宜的灰色或白色垃圾以腾出一个栏位（在商人处则出售）。", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "背包满了？让最便宜的垃圾腾地方，绝不动值得留下的东西。", -- draft
	["Discard Button"] = "丢弃按钮", -- draft
	["A button on the bag window that throws away your cheapest junk item (sells it at a vendor). Never consumables, materials, quest items or your Restock list. A white item asks first."] = "背包窗口上的按钮，丢弃你最便宜的垃圾（在商人处则出售）。不会丢弃消耗品、材料、任务物品或补货清单中的物品。白色物品会先询问。", -- draft
	["Discard Button On Loot"] = "拾取窗口上的丢弃按钮", -- draft
	["The same button on the loot window. It only throws something away for loot worth more."] = "拾取窗口上的同一按钮。只有在拾取物更值钱时才会丢弃。", -- draft
	["Never Throw Away Items Worth"] = "绝不丢弃价值达到", -- draft
	["Stacks worth this many silver or more are never thrown away (they can still be sold)."] = "价值达到此银币数的堆叠永远不会被丢弃（仍可出售）。", -- draft
	-- Gains
	["Gains"] = "收获", -- draft
	["Short lines beside your character for what you just gained: skill ups, items and money. Move them in Edit Layout."] = "角色旁的短文字显示你刚获得的东西：技能提升、物品和金钱。可在“编辑布局”中移动。", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "每个技能点、每件新物品，都在角色旁轻声告诉你，然后消失。", -- draft
	["Show"] = "显示", -- draft
	["Skill Ups"] = "技能提升", -- draft
	["A line when a skill goes up: weapons, Defense, professions and languages."] = "技能提升时显示一行：武器、防御、专业和语言。", -- draft
	["Show Skill Values"] = "显示技能数值", -- draft
	["The skill's new value and its cap, such as 57 / 80."] = "技能的新值和上限，例如 57 / 80。", -- draft
	["Looted & Received Items"] = "拾取和收到的物品", -- draft
	["A line for each item you get: loot, quest rewards, crafts, mail and trades."] = "获得每件物品时显示一行：拾取、任务奖励、制造、邮件和交易。", -- draft
	["Bought Items"] = "购买的物品", -- draft
	["A line for what you buy from a merchant."] = "从商人处购买物品时显示一行。", -- draft
	["Junk Items"] = "垃圾物品", -- draft
