	["Item Names In Quality Colour"] = "物品名显示品质颜色", -- draft
	["Item names in their quality colour. Off: in the text colour, easier to read on bright ground."] = "物品名以品质颜色显示。关闭：以文字颜色显示，在明亮背景上更易读。", -- draft
	["Lines"] = "行", -- draft
	["How long each line stays before it fades."] = "每行在淡出前停留多久。", -- draft
	-- Meter
	["Damage Meter"] = "伤害统计", -- draft
	["MelloUI's damage meter: numbers on your frames, a race bar in fights, a summary after, and a fight history. Replaces the game's meter."] = "MelloUI 的伤害统计：框体上的数字、战斗中的竞速条、战后总结和战斗历史。取代游戏的统计。", -- draft
	["How the fight went, where you already look."] = "战斗打得怎样，就在你本来就看的地方。", -- draft
	["Your Values"] = "你的数值", -- draft
	["Your damage per second, run total and healing per second beside your player frame."] = "你的每秒伤害、本轮总计和每秒治疗，显示在你的玩家框体旁边。", -- draft
	["Party Values"] = "队伍数值", -- draft
	["The same numbers beside each party frame, and beside your own when it shows in your party."] = "每个小队框体旁边的相同数字；你自己的框体显示在小队中时也有。", -- draft
	["On Raid-Style Frames"] = "团队样式框体上", -- draft
	["A damage or healing number on each raid-style frame. Point at a frame for all three."] = "每个团队风格框体上的伤害或治疗数字。指向框体可查看三项。", -- draft
	["Race Bar"] = "竞速条", -- draft
	["In a fight, a race bar of your group's damage, with you highlighted. Point at it for everyone's numbers."] = "战斗中显示小队伤害的竞速条，突出显示你。指向它查看所有人的数字。", -- draft
	["Race Bar Shows"] = "竞速条显示", -- draft
	["What the race bar compares. Auto: healing as a healer, damage otherwise."] = "竞速条比较的内容。自动：治疗者比较治疗，否则比较伤害。", -- draft
	["Auto"] = "自动", -- draft
	["Damage"] = "伤害", -- draft
	["Healing"] = "治疗", -- draft
	["Race Bar Pins"] = "竞速条标记", -- draft
	["How many players the race bar shows. You are always on it."] = "竞速条显示多少名玩家。你始终在其中。", -- draft
