	["Fight Summary"] = "战斗总结", -- draft
	["After a fight, a short summary in the widget column: your damage, DPS and rank. Click it for the full fight."] = "战斗后在小部件栏中显示简短总结：你的伤害、DPS 和排名。点击查看完整战斗。", -- draft
	["Fight History"] = "战斗历史", -- draft
	["A window with every fight of this session: damage, healing and your spells. Opens from the chat's buttons."] = "包含本次会话每场战斗的窗口：伤害、治疗和你的法术。从聊天按钮打开。", -- draft
	["Fights Kept"] = "保留战斗数", -- draft
	["How many fights the history keeps. It starts empty at each login."] = "历史保留多少场战斗。每次登录时清空。", -- draft
	-- SwingTimers
	["Swing Timers"] = "挥击计时条", -- draft
	["Your swing timer as a badge on your target's nameplate. Replaces the game's swing timers."] = "在目标姓名板上以徽章显示你的挥击计时器。取代游戏的挥击计时器。", -- draft
	["Every swing and shot at a glance."] = "每次挥击和射击，一目了然。", -- draft
	["Shots"] = "射击", -- draft
