	["Melee Swings"] = "近战挥击", -- draft
	["Your main hand's swings on the swing badge. Wand shots too."] = "挥击徽章上的主手挥击。魔杖射击也包括在内。", -- draft
	["Off Hand"] = "副手", -- draft
