	["The space between the name and the medallion."] = "名字与徽章之间的间距。", -- draft
	["Role Ring"] = "职责圆环", -- draft
	["A ring in the member's role colour around the medallion: green healer, blue tank, red damage."] = "徽章周围的职责颜色环：绿色治疗、蓝色坦克、红色伤害。", -- draft
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "仅限野外：在副本中游戏不让插件使用友方姓名板", -- draft
	-- Sparkles
	["Loot Sparkles"] = "拾取闪光", -- draft
	["Keeps the sparkle on lootable quest items, and adds glints over nearby ore and herbs."] = "保留可拾取任务物品的闪光，并在附近的矿石和草药上添加闪烁。", -- draft
	["What you can loot, at a glance."] = "能拾取什么，一目了然。", -- draft
	["Quest Item Sparkles"] = "任务物品闪光", -- draft
	["Keeps the game's sparkle on lootable quest items. Turning it off takes effect after a game restart."] = "保留游戏在可拾取任务物品上的闪光。关闭后需重启游戏才生效。", -- draft
	["Ore Veins"] = "矿脉", -- draft
	["Golden glints over the nearest ore vein: bright when you can mine it, grey when your skill is too low."] = "最近矿脉上的金色闪烁：可采集时明亮，技能不足时灰色。", -- draft
	["Herbs"] = "草药", -- draft
	["The same glints over the nearest herb."] = "最近的草药上同样的闪烁。", -- draft
	["Quest Objects"] = "任务物体", -- draft
	["The same glints over the nearest quest object."] = "最近的任务物体上同样的闪烁。", -- draft
	-- CustomSounds
	["Custom Sounds"] = "自定义音效", -- draft
	["Replaces the interface's sounds with MelloUI's own, in the set of your skin: clicks, windows, bags, gear, vendors and more. The Default skin keeps the game's own sounds."] = "用 MelloUI 自己的音效替换界面音效，按你的外观风格使用对应的音效组：点击、窗口、背包、装备、商人等。默认外观风格保留游戏自己的音效。", -- draft
	["Every click, page, pouch and latch of the interface, re-recorded: light and clean for Modern, iron and leather for Oldschool."] = "界面的每一次点击、翻页、钱袋和搭扣都重新录制：现代风格轻快干净，Oldschool 则是钢铁与皮革。", -- draft
