	["Group Finder"] = "队伍查找器", -- draft
	["Joining and leaving a queue, and a bell when your group is ready."] = "加入和离开队列的声音，小队就绪时一声铃响。", -- draft
	["A workbench sound when you craft."] = "制造时的工作台声音。", -- draft
