	["Crowd Control"] = "控制", -- draft
	["Large CC Icon Above Name"] = "名字上方大号控制图标", -- draft
	["A large crowd-control icon above the name. Needs the game's Crowd Control nameplate option on."] = "名字上方的大控制图标。需要开启游戏的姓名板控制选项。", -- draft
