	["Threat Line"] = "仇恨线", -- draft
	["In group fights, a thin line on an enemy's bar showing how close it is to turning on you. For tanks, it turns red when you lose a mob."] = "小队战斗中，敌人条上的一条细线显示它离转向你有多近。坦克失去怪物时它会变红。", -- draft
	["Combo Points"] = "连击点数", -- draft
	["Rogues and cat druids: your combo points on your target's nameplate."] = "盗贼和猎豹形态的德鲁伊：你的连击点显示在目标姓名板上。", -- draft
	["Combo Point Size"] = "连击点数大小", -- draft
	["The size of each combo point."] = "每个连击点的大小。", -- draft
	["Moves the combo points left or right on the nameplate."] = "在姓名板上左右移动连击点。", -- draft
	["Moves the combo points up or down on the nameplate. The name moves out of their way."] = "在姓名板上上下移动连击点。名字会让开它们。", -- draft
	["Swing Badge"] = "挥击徽章", -- draft
	["Swing Badge Size"] = "攻击徽章大小", -- draft
	["The size of your swing timer's weapon badge on your target's nameplate, or over the Personal Display."] = "目标姓名板上或个人显示上方你的攻击计时器武器徽章的大小。", -- draft
	-- PlateImpact
	["Impact Effects"] = "打击效果", -- draft
	["Your target's nameplate reacts to the fight: hits flash, crits glow, interrupted casts shatter."] = "目标姓名板对战斗作出反应：命中闪光、暴击发光、被打断的施法碎裂。", -- draft
	["Every hit lands on the plate, not only in a number."] = "每一击都打在姓名板上，而不只是一个数字。", -- draft
	["Hit Flash"] = "命中闪光", -- draft
	["Your target's bar flashes when it is hit; gold for a critical hit."] = "目标的条在被命中时闪光；暴击时为金色。", -- draft
	["Damage Chunk"] = "伤害块", -- draft
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "被命中扣掉的那段条会亮一会儿再消退，让你看清每次命中的大小。", -- draft
	["Crit Glow"] = "暴击光晕", -- draft
	["A gold glow bursts around your target's bar on a critical hit."] = "暴击时目标条周围迸发金色光晕。", -- draft
	["Kill Flash"] = "击杀闪光", -- draft
	["A killing blow flashes the bar out instead of the plate just vanishing."] = "致命一击让条闪光消失，而不是姓名板直接消失。", -- draft
	["Dodge And Miss"] = "躲闪和未命中", -- draft
	["Dodge, parry and miss words flick off the side of your target's plate."] = "躲闪、招架和未命中的文字从目标姓名板侧边弹出。", -- draft
	["Cast Warning"] = "施法警告", -- draft
	["Your target's cast bar glows hotter near the end, and shatters when interrupted."] = "目标的施法条接近结束时越来越炽热，被打断时碎裂。", -- draft
	["On Your Target Frame"] = "在你的目标框体上", -- draft
	["Your target frame's health bar shows the same hit effects."] = "目标框体的生命条显示相同的命中效果。", -- draft
	-- Tooltip
	["Tooltip"] = "鼠标提示", -- draft
	["Dark flat tooltips with class coloured names and borders, plus placement options."] = "深色扁平的鼠标提示，名字和边框为职业颜色，另有位置选项。", -- draft
	["Dark, flat and out of the way, with names in the colour of their class."] = "深色、扁平、不碍事，名字为职业颜色。", -- draft
	["Background"] = "背景", -- draft
	["The tooltips' background: Dark, the game's own, or (with Oldschool) Painted or Parchment."] = "说明条的背景：暗色、游戏自带，或（配合 Oldschool）手绘或羊皮纸。", -- draft
	["Painted"] = "手绘", -- draft
	["Parchment"] = "羊皮纸", -- draft
	["Dark"] = "深色", -- draft
	["Game"] = "游戏", -- draft
	["Backdrop Opacity"] = "背景不透明度", -- draft
	["How solid the Dark background is."] = "暗色背景的不透明度。", -- draft
	["Class / Reaction Border"] = "职业 / 关系边框", -- draft
	["Colours a unit tooltip's border by class (players) or reaction (NPCs)."] = "按职业（玩家）或反应（NPC）为单位说明条的边框着色。", -- draft
	["Units"] = "单位", -- draft
	["Class / Reaction Health Colour"] = "职业 / 关系生命颜色", -- draft
	["The tooltip's health bar in the class or reaction colour instead of green."] = "说明条生命条使用职业或反应颜色而不是绿色。", -- draft
	["Hide Health Bar"] = "隐藏生命条", -- draft
	["Hides the health bar under unit tooltips."] = "隐藏单位说明条下方的生命条。", -- draft
	["Hide Issue Report Line"] = "隐藏问题报告行", -- draft
	["Hides the beta's \"Press F6 to submit an issue\" line in tooltips."] = "隐藏说明条中测试版的“按 F6 提交问题”一行。", -- draft
	["Coloured Lines"] = "彩色行", -- draft
	["Colours tooltip lines: guild, faction, level difficulty and quest progress."] = "为说明条各行着色：公会、阵营、等级难度和任务进度。", -- draft
	["Hide Unit Tooltips In Combat"] = "战斗中隐藏单位鼠标提示", -- draft
	["No unit tooltips in combat."] = "战斗中不显示单位说明条。", -- draft
	["Fade Delay"] = "淡出延迟", -- draft
	["How long a tooltip stays after your mouse leaves."] = "鼠标离开后说明条停留多久。", -- draft
	["Placement"] = "位置", -- draft
	["Anchor"] = "锚点", -- draft
	["Where tooltips appear."] = "鼠标提示出现的位置。", -- draft
	["Default (Edit Mode position)"] = "默认（编辑模式中的位置）", -- draft
	["At the cursor"] = "在光标处", -- draft
	["Right of the cursor"] = "光标右侧", -- draft
	["Scale"] = "缩放", -- draft
	["The size of tooltips."] = "说明条的大小。", -- draft
	-- UnitFrames
	["Centred names, a clear name band and no combat flash for player, target and focus; the party's levels and the names' soft bands."] = "玩家、目标和焦点的名字居中、名字横带清晰、没有战斗闪光；小队的等级和名字的柔和横带。", -- draft
	["Player, target and focus, centred and calm."] = "玩家、目标和焦点，居中又安静。", -- draft
	["MelloUI Frames"] = "MelloUI框体", -- draft
	["The unit frames in MelloUI's look: a gold portrait ring, a level badge and gold-lined borders. Off: the game's own art."] = "MelloUI 外观的单位框体：金色头像环、等级徽章和金线边框。关闭：游戏自己的美术。", -- draft
	["Target of Target"] = "目标的目标", -- draft
	["Shows who your target is targeting, under the target frame, and who your focus is targeting, under the focus frame. This is the game's own Target of Target setting. A change here takes effect after a /reload."] = "在目标框体下方显示你的目标正在瞄准谁，在焦点框体下方显示你的焦点正在瞄准谁。这是游戏自带的“目标的目标”设置。此处的更改在 /reload 后生效。", -- draft
	["Flip Horizontally"] = "水平翻转", -- draft
	["Mirrors the party frames for a party on the right of the screen: portraits on the right."] = "为位于屏幕右侧的小队镜像小队框体：头像在右。", -- draft
	["Names"] = "名字", -- draft
	["Name Font"] = "名字字体", -- draft
	["The font of names on the unit frames and party portraits. Shared: the interface font."] = "单位框体和小队头像上名字的字体。共享：界面字体。", -- draft
	["Glows"] = "光晕", -- draft
	["Hide Combat Flash"] = "隐藏战斗闪光", -- draft
	["Hides the threat glow on the unit frames. Off: a soft halo round each frame's own shape while it has threat, amber when close to pulling, red while holding the enemy."] = "隐藏单位框体上的威胁光芒。关闭时：框体有威胁时沿其自身形状显示柔和光环，接近拉怪时为琥珀色，稳住敌人时为红色。", -- draft
	["Hide Status Glow"] = "隐藏状态光晕", -- draft
	["Hides the resting and combat glow around your portrait, and your pet's attack glow."] = "隐藏头像周围的休息和战斗光晕，以及宠物的攻击光晕。", -- draft
	["Hide PvP Badge"] = "隐藏PvP徽章", -- draft
	["Hides the PvP badge beside the portraits."] = "隐藏头像旁的 PvP 徽章。", -- draft
	["Hide Heal Numbers"] = "隐藏治疗数字", -- draft
	["Your portrait no longer shows the green numbers of the heals you take. Damage, misses and mana gains still show."] = "你的头像不再显示你受到治疗的绿色数字。伤害、未命中和法力获得仍会显示。", -- draft
	["Frame Art"] = "框体美术", -- draft
	-- Fader
	["Fader"] = "淡出", -- draft
	["Fades parts of the interface while you don't need them: out of combat, or until you point at them."] = "在你不需要时淡出界面的部分：脱离战斗时，或直到你指向它们。", -- draft
	["Your interface, only when you need it."] = "你的界面，只在需要时出现。", -- draft
	["Fade Everything"] = "全部淡出", -- draft
	["Sets every part below to In Combat: the interface fades out of combat and comes back in a fight."] = "将下方每个部分设为“战斗中”：脱离战斗时界面淡出，战斗时恢复。", -- draft
	["Fade"] = "淡出", -- draft
	["Fade Nothing"] = "全不淡出", -- draft
	["Sets every part below to Always: nothing fades."] = "将下方每个部分设为“始终”：不淡出任何东西。", -- draft
	["Reset"] = "重置", -- draft
	["Faded Opacity"] = "淡出不透明度", -- draft
	["How visible a faded part stays. 0%: hidden until needed."] = "淡出后部分的可见程度。0%：需要时才显示。", -- draft
	["Fade After"] = "淡出前等待", -- draft
	["How long a part waits before fading, after a fight or after your mouse leaves."] = "部分在淡出前等待多久：战斗结束后或鼠标离开后。", -- draft
	["Fade Speed"] = "淡出速度", -- draft
	["How long the fade takes. Coming back is always quick."] = "淡出持续多久。恢复总是很快。", -- draft
	["Show With A Target"] = "有目标时显示", -- draft
	["In Combat parts also come back while you have a target."] = "有目标时，“战斗中”的部分也会恢复。", -- draft
	["Also Show On Mouseover"] = "鼠标悬停时也显示", -- draft
	["In Combat parts also come back while your mouse is over them."] = "鼠标悬停时，“战斗中”的部分也会恢复。", -- draft
	["Your own frame. In Combat, it also returns while you are hurt, low on mana or dead. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "你自己的框体。“战斗中”时，受伤、法力不足或死亡时也会恢复。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Pet Frame Too"] = "宠物框体也一起", -- draft
	["Your pet's frame fades with the player frame and returns while your pet is hurt."] = "宠物框体随玩家框体淡出，宠物受伤时恢复。", -- draft
	["Your target's frame and its target. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "目标的框体及其目标。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Your focus's frame. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "焦点的框体。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Party Frames"] = "小队框体", -- draft
	["The party frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "小队框体。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The raid frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "团队框体。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Your buffs and debuffs. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "你的增益和减益。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The reminder buttons beside your portrait. A new reminder doesn't bring them back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "头像旁的提醒按钮。新的提醒不会让它们恢复。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The Personal Display's bars. In Combat, they also return while you cast. Always: never faded. In Combat: faded out of combat."] = "个人显示的条。“战斗中”时，施法时也会恢复。始终：从不淡出。战斗中：脱离战斗时淡出。", -- draft
	["Main Action Bar"] = "主动作条", -- draft
	["The main action bar. Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "主动作条。淡出时按键仍可用。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "淡出时按键仍可用。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Stance & Pet Bar"] = "姿态条和宠物条", -- draft
	["The stance, form and pet bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "姿态、形态和宠物条。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Micro Menu"] = "微型菜单", -- draft
	["The micro menu. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "微型菜单。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Bag Bar"] = "背包栏", -- draft
	["The bag bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "背包栏。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The experience and reputation bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "经验条和声望条。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The chat windows, tabs and buttons. They return while you type. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "聊天窗口、标签和按钮。输入时恢复。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The minimap and the Services bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "微缩地图和服务栏。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Quest Tracker"] = "任务追踪器", -- draft
	["MelloUI's Quest Tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "MelloUI 的任务追踪器。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Objective Tracker"] = "目标追踪器", -- draft
	["The game's objective tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "游戏的目标追踪器。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["Widget Column"] = "小部件栏", -- draft
	["The widget column. A new widget doesn't bring it back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "小部件栏。新的小部件不会让它恢复。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["World Marker"] = "世界标记", -- draft
	["Route's World Marker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Route 的世界标记。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	["The FPS and latency readout. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "帧数和延迟显示。始终：从不淡出。战斗中：脱离战斗时淡出。鼠标悬停：淡出直到你指向它。", -- draft
	-- QuestAuto
	["Auto Accept & Hand In"] = "自动接受和交任务", -- draft
	["Accepts quests and hands them in as you talk to their givers, off until you switch it on."] = "与任务给予者交谈时接受任务并交任务，开启前保持关闭。", -- draft
	["Talk, and the quest is yours. Hold Shift to read it first."] = "说句话，任务就是你的了。按住Shift先读一读。", -- draft
	["Auto Accept Quests"] = "自动接受任务", -- draft
	["Accepts quests as soon as a giver offers them. Repeatable, daily and shared quests are left to you."] = "任务发布者一提供任务就接受。可重复、日常和共享任务留给你处理。", -- draft
	["Auto Hand In"] = "自动交任务", -- draft
	["Hands in finished quests as soon as you talk to the NPC. A choice of rewards waits for you."] = "与 NPC 对话时立即交付已完成的任务。需要选择奖励时会等你。", -- draft
	["Take The Upgrade"] = "选择升级", -- draft
	["With a choice of rewards, takes the best upgrade you can use, or the one that sells for the most."] = "需要选择奖励时，选你能用的最佳提升，或卖价最高的。", -- draft
	["Skip Key"] = "跳过键", -- draft
	["Hold this key while talking to an NPC to stop the automatic accept and hand-in."] = "与 NPC 对话时按住此键，停止自动接受和交付。", -- draft
