	["Ctrl"] = "Ctrl", -- draft
	["Alt"] = "Alt", -- draft
	-- HealerFrames
	["Healer Frames"] = "治疗者框体", -- draft
	["Incoming heals on the unit frames, and a glow in a debuff's colour round any frame whose unit has a debuff to remove."] = "单位框体上的预计治疗，以及在单位有可移除减益的框体周围显示减益颜色的光晕。", -- draft
	["See the heals coming in, and who needs a cleanse."] = "看清即将到来的治疗，以及谁需要驱散。", -- draft
	["Incoming Heals"] = "预计治疗", -- draft
	["Incoming heals and shields shown on the player, target and focus health bars."] = "玩家、目标和焦点生命条上的即将到来的治疗和护盾。", -- draft
	["Debuff Glow"] = "减益光晕", -- draft
	["A glow in the debuff's colour around a friend's frame while they have a debuff that can be removed."] = "友方身上有可驱散的减益时，其框体周围显示减益颜色的光晕。", -- draft
	["Debuff Glow Shows"] = "减益光晕显示", -- draft
	["Which debuffs light a frame: any that can be removed, the ones your group can remove, or only yours."] = "哪些减益会点亮框体：任何可驱散的、你的小队能驱散的，或仅你能驱散的。", -- draft
	["Every Dispellable Debuff"] = "所有可驱散的减益", -- draft
	["Ones The Group Can Dispel"] = "队伍能驱散的", -- draft
	["Ones I Can Dispel"] = "我能驱散的", -- draft
	-- ActionBars
	["MelloUI on the bars: its own action, stance, pet and possess bars, micro menu, bag bar and experience bars, with their backdrops, button frames, colours and timers. Off: the game's own bars, untouched."] = "动作条上的 MelloUI：它自己的动作条、姿态条、宠物条和控制条、微型菜单、背包条和经验条，以及它们的背景、按钮边框、颜色和计时。关闭：游戏自己的动作条，保持原样。", -- draft
	["The experience and reputation bars in MelloUI's look. Off: the game's own frame."] = "MelloUI 外观的经验条和声望条。关闭：游戏自己的边框。", -- draft
	["Hide Page Arrows"] = "隐藏翻页箭头", -- draft
	["Hides the main bar's page number and arrows. Paging keys still work."] = "隐藏主动作条的页码和箭头。翻页按键仍可用。", -- draft
	["Hide Bar Art"] = "隐藏动作条美术", -- draft
	["Hides the main bar's art, like the other bars. With UI Modifications off: only on your own Edit Mode layouts, after a /reload."] = "像其他动作条一样隐藏主动作条的装饰。关闭界面修改时：仅在你自己的编辑模式布局中，/reload 后生效。", -- draft
	["A backdrop around Action Bar 1. Neighbours with a backdrop share one."] = "动作条 1 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 2. Neighbours with a backdrop share one."] = "动作条 2 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 3. Neighbours with a backdrop share one."] = "动作条 3 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 4. Neighbours with a backdrop share one."] = "动作条 4 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 5. Neighbours with a backdrop share one."] = "动作条 5 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 6. Neighbours with a backdrop share one."] = "动作条 6 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 7. Neighbours with a backdrop share one."] = "动作条 7 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around Action Bar 8. Neighbours with a backdrop share one."] = "动作条 8 周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around the stance bar. Neighbours with a backdrop share one."] = "姿态条周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around the pet bar. Neighbours with a backdrop share one."] = "宠物条周围的底板。相邻的有底板的条共用一个。", -- draft
	["Possess Bar"] = "附身条", -- draft
	["A backdrop around the possess bar. Neighbours with a backdrop share one."] = "控制条周围的底板。相邻的有底板的条共用一个。", -- draft
	["Totem Bar"] = "图腾栏", -- draft
	["A backdrop around the totem bar. Neighbours with a backdrop share one."] = "图腾条周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around the micro menu. Neighbours with a backdrop share one."] = "微型菜单周围的底板。相邻的有底板的条共用一个。", -- draft
	["A backdrop around the bag bar. Neighbours with a backdrop share one."] = "背包栏周围的底板。相邻的有底板的条共用一个。", -- draft
	["Experience Bar"] = "经验条", -- draft
	["A backdrop around the experience bar (the reputation bar in its place at the top level). Neighbours with a backdrop share one."] = "经验条周围的底板（满级时由声望条代替）。相邻的有底板的条共用一个。", -- draft
	["Reputation Bar"] = "声望条", -- draft
