	-- ActionButtons
	["Action Buttons"] = "动作按钮", -- draft
	["Lights an action button while its key is held, and colours its icon by range and resources."] = "按住按键时点亮动作按钮，并按距离和资源为其图标着色。", -- draft
	["See which button you press, and which spell cannot reach its target."] = "看清你按的是哪个按钮，以及哪个法术够不着目标。", -- draft
	["Action buttons in MelloUI's frame: gold when active, red out of range. Off: the game's own frames."] = "MelloUI 边框的动作按钮：激活时金色，超出范围时红色。关闭：游戏自己的边框。", -- draft
	["Cooldown Ready Flash"] = "冷却就绪闪光", -- draft
	["A gold light runs around a button when its cooldown ends."] = "冷却结束时，一道金光绕按钮一周。", -- draft
	["Light While Pressed"] = "按下时发光", -- draft
	["A button lights up while you press it."] = "按下时按钮会亮起。", -- draft
	["Range And Resource Colours"] = "距离和资源颜色", -- draft
	["Icons turn red out of range, blue without enough mana, and grey when unusable."] = "超出范围时图标变红，法力不足时变蓝，不可用时变灰。", -- draft
	-- CooldownTweaks
	["Cooldown Manager Tweaks"] = "冷却管理器调整", -- draft
	["Centred rows, key bindings, a light while pressed and the count size on the game's Cooldown Manager."] = "游戏冷却管理器的行居中、快捷键、按下时发光以及数字大小。", -- draft
	["Your cooldowns, in the middle, with their keys on them."] = "你的冷却，在中间，按键就在上面。", -- draft
	["Centre Rows"] = "行居中", -- draft
	["A shorter row of cooldown icons sits centred under the others."] = "较短的一行冷却图标在其他行下方居中。", -- draft
	["Key Bindings"] = "快捷键", -- draft
	["The key bound to a cooldown's spell, on the icon's corner."] = "冷却法术绑定的按键，显示在图标角落。", -- draft
	["A cooldown's icon lights up while you press its action button."] = "按下对应动作按钮时，冷却图标会亮起。", -- draft
	["Count Size"] = "数字大小", -- draft
	["The size of the charges and stacks numbers on the icons."] = "图标上充能和层数数字的大小。", -- draft
	-- BagWindow
	["Bags by Kind"] = "背包分类", -- draft
	["Your bags in one window, sorted by kind: new items, gear, quest items, consumables, junk and more."] = "所有背包在一个窗口中，按类别排序：新物品、装备、任务物品、消耗品、垃圾等。", -- draft
	["A place for everything, and everything under its heading."] = "物各有所，各归其题。", -- draft
	["Kinds"] = "类别", -- draft
	["The kinds your bag window sorts items into, top first. Drag to reorder, untick to hide, Add kind to make your own; double-click a name to rename it, its cog opens its settings."] = "背包窗口用来归类物品的类别，最上面的优先。拖动排序，取消勾选隐藏，“添加类别”创建你自己的；双击名字重命名，齿轮打开其设置。", -- draft
	["Items You Placed"] = "你放置的物品", -- draft
	["While you hold an item, drop it on a kind's + to always sort it there. Forget puts every placed item back."] = "拿着物品时，把它放到某个类别的 + 上，它就总会归入那里。“忘记”会把所有放置过的物品复原。", -- draft
	["Forget"] = "忘记", -- draft
	["Bank by Kind"] = "银行分类", -- draft
	["Your bank sorted by the same kinds as your bags. Off: the game's grid."] = "银行按与背包相同的类别排序。关闭：游戏的网格。", -- draft
	["Recent Lasts"] = "“最近”保留时长", -- draft
	["How long new items stay under Recent: until you close your bags, until you point at them, or 5 minutes."] = "新物品在“最近”中停留多久：直到关闭背包、直到你指向它们，或 5 分钟。", -- draft
	["Until The Bags Close"] = "直到关闭背包", -- draft
	["Until Hovered"] = "直到指向", -- draft
	["For 5 Minutes"] = "5分钟", -- draft
	["Columns"] = "列数", -- draft
	["How many slots wide the bag window is."] = "背包窗口有多少格宽。", -- draft
	["Item Size"] = "物品大小", -- draft
	["The size of the item slots. 37 is the game's size."] = "物品格的大小。37 为游戏大小。", -- draft
	["Fold Empty Slots"] = "折叠空栏位", -- draft
	["All empty slots shown as one, with their count."] = "所有空格合并为一格，并显示数量。", -- draft
	["Sort Items By"] = "物品排序方式", -- draft
	["How items are ordered inside each kind."] = "每个类别内物品的排序方式。", -- draft
	["Quality"] = "品质", -- draft
	["Name"] = "名字", -- draft
	["Newest First"] = "最新的在前", -- draft
	["Item Level"] = "物品等级", -- draft
	["Loot Flight"] = "拾取飞行", -- draft
	["Looted items fly into your bag window; the rarer the item, the bigger the effect."] = "拾取的物品飞入背包窗口；物品越稀有，效果越大。", -- draft
	["Items Glide"] = "物品滑动", -- draft
	["Items glide to their new slots instead of jumping."] = "物品滑到新位置，而不是跳过去。", -- draft
	["Rolling Money"] = "滚动金钱", -- draft
	["Your money counts up or down to its new amount."] = "你的金钱滚动到新的数额。", -- draft
	["Bags Full Warning"] = "背包已满警告", -- draft
	["The bag window shakes and flashes red when your bags are full."] = "背包满时，背包窗口抖动并闪红。", -- draft
	-- MinimapPanel
	["MelloUI's minimap: its size, square shape and the Services bar under it. Off: the game's own minimap."] = "MelloUI 的微缩地图：大小、方形外观和下方的服务栏。关闭：游戏自己的微缩地图。", -- draft
	["Shape"] = "形状", -- draft
	["The painted minimap's shape: round in its ring, or square in the Square Border."] = "手绘微缩地图的形状：圆环中的圆形，或方形边框中的方形。", -- draft
	["Round"] = "圆形", -- draft
	["Square"] = "方形", -- draft
