	["The border around the square minimap. Painted borders need Oldschool's painted Minimap."] = "方形微缩地图的边框。手绘边框需要 Oldschool 的手绘微缩地图。", -- draft
	["Window frame"] = "窗口边框", -- draft
	["Chat panel"] = "聊天面板", -- draft
	["Heavy, red gems"] = "粗边，红宝石", -- draft
	["Heavy, iron gems"] = "粗边，铁宝石", -- draft
	["Merge With Services"] = "与服务合并", -- draft
	["The square minimap, its zone name and the Services bar share one frame."] = "方形微缩地图、区域名和服务栏共用一个框。", -- draft
	["Width"] = "宽度", -- draft
	["How wide the minimap is. The Quest Tracker under it follows its width."] = "微缩地图的宽度。下方的任务追踪器跟随其宽度。", -- draft
	["Height"] = "高度", -- draft
	["How tall the square minimap is."] = "方形微缩地图的高度。", -- draft
	-- QuestTracker
	["MelloUI's quest tracker in the game's tracker's place. It scrolls, so every quest fits."] = "MelloUI 的任务追踪器，位于游戏追踪器的位置。可以滚动，所有任务都放得下。", -- draft
	["Every watched quest within reach: the tracker scrolls when the list runs long."] = "每个追踪的任务都触手可及：列表变长时追踪器会滚动。", -- draft
	["Tracker"] = "追踪器", -- draft
	["How tall the tracker grows before it scrolls. You can also drag its corner."] = "追踪器在滚动前最多长多高。也可以拖动它的角。", -- draft
	["Match The Minimap's Width"] = "与小地图同宽", -- draft
	["The tracker is as wide as the minimap and sits right under it, following it. Off: use Width below."] = "追踪器与微缩地图同宽，紧贴其下并跟随它。关闭：使用下方的宽度。", -- draft
	["How wide the tracker is when it doesn't match the minimap. You can also drag its corner."] = "不跟随微缩地图时追踪器的宽度。也可以拖动它的角。", -- draft
	["The size of quest titles and section headers. Objectives are one size smaller."] = "任务标题和分区标题的字号。目标小一号。", -- draft
	["Header Text Size"] = "标题文字大小", -- draft
	["The size of the tracker's title."] = "追踪器标题的字号。", -- draft
	["Background Opacity"] = "背景不透明度", -- draft
	["How solid the tracker's background is. At 0% its lines stand on the world, as the game's tracker's do."] = "追踪器背景的不透明程度。为 0% 时，文字直接显示在游戏世界上，与游戏自带的追踪器一样。", -- draft
	["Scroll Step"] = "滚动步长", -- draft
	["How far one turn of the mouse wheel scrolls."] = "鼠标滚轮滚一格滚动多远。", -- draft
	["A quest's usable item beside it. Click to use it out of combat."] = "任务旁显示可使用的任务物品。非战斗中点击使用。", -- draft
	["Progress Motion"] = "进度动画", -- draft
	["Counts roll to their new number, finished objectives get a tick, and a finished quest lights up."] = "计数滚动到新数字，完成的目标打勾，完成的任务会亮起。", -- draft
