	["Your debuffs in a block of their own, with their own place in Edit Layout and their own size and rows. Off: they are the line under your buffs."] = "将你的减益效果放在单独的区块中，在布局编辑中有自己的位置、大小和行。关闭时：它们是增益效果下方的一行。", -- draft
