	["Objective Marks"] = "目标标记", -- draft
	["Marks where your quests' objectives are on the zone map, with their progress. Click a mark for a waypoint."] = "在区域地图上标出任务目标的位置及进度。点击标记设置路径点。", -- draft
	["Only The Tracked Quests"] = "仅追踪的任务", -- draft
