	["Hide The Game's Quest Areas"] = "隐藏游戏的任务区域", -- draft
	["Hides the game's blue quest areas while MelloUI's marks are on."] = "MelloUI 标记开启时，隐藏游戏的蓝色任务区域。", -- draft
	["On The Minimap"] = "在小地图上", -- draft
	["The same marks on the minimap, with an arrow for nearby ones off its edge. Needs Route."] = "微缩地图上的相同标记，边缘外附近的目标用箭头指示。需要 Route。", -- draft
