	-- Route
	["Route"] = "路线", -- draft
	["Draws the way to your waypoint on the world map and the minimap, along real roads."] = "在世界地图和微缩地图上沿真实道路画出前往路径点的路线。", -- draft
	["A trail of gems from here to there, along the roads you have walked before."] = "一串宝石从这里通到那里，沿着你走过的路。", -- draft
