	["Route To The Tracked Quest"] = "前往追踪任务的路线", -- draft
	["Without a map pin, routes to the quest you track: its next objective, then its turn-in."] = "没有地图标记时，引导到你追踪的任务：下一个目标，然后是交付处。", -- draft
	["Fall Back To The First Tracked Quest"] = "退而使用第一个追踪任务", -- draft
	["When no quest is followed, routes to the first quest on the game's watch list."] = "没有跟随任务时，引导到游戏追踪列表中的第一个任务。", -- draft
	["Follow Guide Addons"] = "跟随指南插件", -- draft
	["Shows the current steps of RestedXP and other guide addons in the Quest Tracker and routes to them, hiding the guide's own arrow and window. Off, the guide keeps its own."] = "在任务追踪器中显示RestedXP和其他指南插件的当前步骤并规划路线前往，同时隐藏指南自带的箭头和窗口。关闭后，指南保留自己的箭头和窗口。", -- draft
	["Distance Under The Minimap"] = "小地图下方的距离", -- draft
	["The distance left and the destination under the minimap."] = "微缩地图下方显示剩余距离和目的地。", -- draft
	["Travel Time"] = "旅行时间", -- draft
	["About how long the rest of the way takes, beside the distance."] = "距离旁显示剩余路程大约需要的时间。", -- draft
	["A mark over the destination in the world with its distance; an arrow points the way when it is off screen."] = "世界中目的地上方的标记及距离；目的地在屏幕外时，箭头指示方向。", -- draft
	["Light Beam"] = "光柱", -- draft
	["A slim beam of light over the destination, seen from far away."] = "目的地上方的一道细光柱，远处可见。", -- draft
	["Wisp"] = "小精灵", -- draft
	["A small light flies from you to a new destination and lights it."] = "一个小光点从你飞向新目的地并将其点亮。", -- draft
	["Firefly"] = "萤火虫", -- draft
	["Embers"] = "余烬", -- draft
	["Route Draws In"] = "路线绘入", -- draft
	["A new route grows from you to the destination instead of appearing all at once."] = "新路线从你所在处逐渐延伸到目的地，而不是一次全部出现。", -- draft
	["Arrival Light"] = "到达之光", -- draft
	["The mark sinks into a ring of light when you arrive."] = "到达时标记沉入光环中。", -- draft
	["Marker Sounds"] = "标记音效", -- draft
	["A soft sound when the World Marker appears or changes."] = "世界标记出现或变化时的轻柔声音。", -- draft
	["Arrival"] = "到达", -- draft
	["Arrived Within (yards)"] = "到达范围（码）", -- draft
	["How close you must get for the route to end."] = "离目的地多近时路线结束。", -- draft
	["Flights"] = "飞行", -- draft
	["Flight Map Help"] = "飞行地图帮助", -- draft
