	["Learn Paths While Playing"] = "游戏中学习路径", -- draft
	["Remembers where you walk and fly, so routes follow real roads."] = "记住你走过和飞过的地方，让路线沿真实道路。", -- draft
	-- Chat
	["Clean chat: hidden background and input art, short coloured channel tags, class coloured names."] = "简洁的聊天：隐藏背景和输入框美术，简短的彩色频道标签，职业颜色名字。", -- draft
	["Less frame, more talk. Short channel tags and class colours keep the log readable."] = "少点边框，多点聊天。简短的频道标签和职业颜色让记录易读。", -- draft
	["Chat View"] = "聊天视图", -- draft
	["How the chat looks. Game Windows: the game's windows and tabs. Minimal: one panel with round tabs, each message under its sender, and buttons to pick a channel."] = "聊天的外观。游戏窗口：游戏的窗口和标签。简约：一个带圆形标签的面板，每条消息位于发送者下方，并有选择频道的按钮。", -- draft
	["Game Windows"] = "游戏窗口", -- draft
	["Minimal"] = "极简", -- draft
	["The chat's background: Dark, the game's own, or none."] = "聊天背景：暗色、游戏自带，或无。", -- draft
	["Set The Background Opacity"] = "统一背景不透明度", -- draft
	["Every chat window uses the same background opacity. Off: each keeps its own."] = "所有聊天窗口使用相同的背景不透明度。关闭：各自保留自己的。", -- draft
	["How solid the chat windows' background is."] = "聊天窗口背景的不透明度。", -- draft
	["Border Opacity"] = "边框不透明度", -- draft
	["How solid the painted border around the chat is."] = "聊天周围手绘边框的不透明度。", -- draft
	["Hide Input Box Art"] = "隐藏输入框美术", -- draft
	["Hides the border and background of the chat's input line."] = "隐藏聊天输入行的边框和背景。", -- draft
	["Hide Tab Background"] = "隐藏标签背景", -- draft
	["Hides the background behind the chat tabs. Their names stay."] = "隐藏聊天标签后的背景。名字保留。", -- draft
	["Tabs Only On Mouseover"] = "仅鼠标悬停时显示标签", -- draft
	["The chat tab names show only while your mouse is over the chat. Flashing tabs stay visible."] = "只有鼠标在聊天上时才显示聊天标签名。闪烁的标签始终可见。", -- draft
	["Input Box On Top"] = "输入框在上方", -- draft
	["The input line sits above the chat instead of below it."] = "输入行位于聊天上方而不是下方。", -- draft
	["Input Box Only While Typing"] = "仅在打字时显示输入框", -- draft
	["The input line shows only while you type."] = "输入行只在输入时显示。", -- draft
	["Chat Buttons"] = "聊天按钮", -- draft
	["The column of chat buttons beside the chat: Friends, Channels and the chat menu."] = "聊天旁的按钮栏：好友、频道和聊天菜单。", -- draft
	["Smooth Scrolling"] = "平滑滚动", -- draft
	["The mouse wheel scrolls the chat smoothly instead of a line at a time."] = "鼠标滚轮平滑滚动聊天，而不是逐行跳动。", -- draft
	["Channels"] = "频道", -- draft
	["Short Channel Tags"] = "简短频道标签", -- draft
	["Short coloured tags instead of [Guild], [Party], [1. General] and so on."] = "用简短彩色标签代替 [公会]、[小队]、[1. 综合] 等。", -- draft
	["Hide Brackets"] = "隐藏方括号", -- draft
	["Removes the brackets around the short tags."] = "去掉简短标签周围的括号。", -- draft
	["Whisper Popup Window"] = "悄悄话弹窗", -- draft
	["Each whisper opens a small window for that person, with a box to answer in. Whispers still show in the chat."] = "每条悄悄话为对方打开一个小窗口，带回复框。悄悄话仍会显示在聊天中。", -- draft
	-- CombatText
	["The text around your character in a fight (damage taken, heals, procs) in MelloUI's look, or the game's own."] = "战斗中角色周围的文字（受到的伤害、治疗、触发）使用 MelloUI 外观或游戏自带。", -- draft
	["Your hits taken, heals and procs in MelloUI's soft look, or the game's own text."] = "你受到的打击、治疗和触发，使用MelloUI柔和的外观，或游戏自己的文字。", -- draft
	["Combat Text Style"] = "战斗文字风格", -- draft
	["How the text around your character is shown. Game: the game's own. Lanes: damage taken left, healing right. Feed: one column over your portrait. Classic: one stream over your head."] = "角色周围文字的显示方式。游戏：游戏自带。分道：受到伤害在左，治疗在右。信息流：头像上方一列。经典：头顶一股文字流。", -- draft
	["Game (Blizzard)"] = "游戏（暴雪）", -- draft
	["Lanes: round your character"] = "分道：围绕你的角色", -- draft
	["Feed: over your portrait"] = "信息流：在你的头像上方", -- draft
	["Classic: one stream, restyled"] = "经典：一道文字流，换了新样式", -- draft
	["Your Damage"] = "你的伤害", -- draft
	["How your damage numbers over enemies look. Game: the game's own. Rise, Beside, Fan or Stack: MelloUI's, shown solo; in a group the game's show."] = "敌人头顶你的伤害数字外观。游戏：游戏自带。上升、侧边、扇形或堆叠：MelloUI 的，单人时显示；组队时显示游戏的。", -- draft
	["Rise: up from the enemy"] = "上升：从敌人身上向上", -- draft
	["Beside: up from the plate's side"] = "侧边：从姓名板侧边向上", -- draft
	["Fan: up, left and right"] = "扇形：向上、左和右", -- draft
	["Stack: a column beside the enemy"] = "堆叠：敌人旁的一列", -- draft
	["Your Damage Size"] = "你的伤害大小", -- draft
	["The size of your damage numbers over enemies."] = "敌人头顶你的伤害数字大小。", -- draft
	["Plays sample lines in the chosen style."] = "以所选样式播放示例文字。", -- draft
	["a short burst in the chosen style"] = "以所选风格播放一小段", -- draft
	["Text Around You"] = "你周围的文字", -- draft
	["The size of the text around your character. Crits are a third bigger."] = "角色周围文字的大小。暴击大三分之一。", -- draft
	["Notices In Title Font"] = "通知使用标题字体", -- draft
	["Procs and auras in the title font. Off: the text font."] = "触发和光环使用标题字体。关闭：使用正文字体。", -- draft
	["Shade Size"] = "阴影大小", -- draft
	["The size of the soft shadow behind combat text. 0: none."] = "战斗文字后柔和阴影的大小。0：无。", -- draft
	["Lane Spread"] = "分道间距", -- draft
	["How far left and right of your character the damage and healing lanes run."] = "伤害和治疗分道向角色左右延伸多远。", -- draft
	["Most Lines"] = "最多行数", -- draft
	["The most lines shown at once. The oldest goes first."] = "同时显示的最多行数。最旧的先消失。", -- draft
	["Damage Taken"] = "受到的伤害", -- draft
	["Damage you take."] = "你受到的伤害。", -- draft
	["Healing and shields you get."] = "你得到的治疗和护盾。", -- draft
	["Procs & Auras"] = "触发和光环", -- draft
	["Procs, auras gained or lost, interrupts and dispels."] = "触发、获得或失去的光环、打断和驱散。", -- draft
	["Dodge, Parry & Block"] = "躲闪、招架和格挡", -- draft
	["Attacks that miss you: dodge, parry, block, absorb, resist and immune."] = "未命中你的攻击：躲闪、招架、格挡、吸收、抵抗和免疫。", -- draft
	["Resources Gained"] = "获得的资源", -- draft
	["Mana, rage, energy and focus you gain."] = "你获得的法力、怒气、能量和集中值。", -- draft
	["Entering & Leaving Combat"] = "进入和离开战斗", -- draft
	["A short line when a fight starts and ends."] = "战斗开始和结束时一行短文字。", -- draft
	["Reputation & Honor"] = "声望和荣誉", -- draft
	["Reputation and honor you gain."] = "你获得的声望和荣誉。", -- draft
	["Damage Over Enemies"] = "敌人头上的伤害", -- draft
	["Your damage numbers over enemies (the game's own)."] = "敌人头顶你的伤害数字（游戏自带）。", -- draft
	["DoT Ticks Over Enemies"] = "敌人头上的持续伤害跳数", -- draft
	["Your damage over time ticks over enemies (the game's own)."] = "敌人头顶你的持续伤害跳数（游戏自带）。", -- draft
	["Pet Damage Over Enemies"] = "敌人头上的宠物伤害", -- draft
	["Your pet's damage over enemies (the game's own)."] = "敌人头顶你宠物的伤害（游戏自带）。", -- draft
	["Healing Over Friends"] = "友方头上的治疗", -- draft
	["Your healing numbers over friends (the game's own)."] = "友方头顶你的治疗数字（游戏自带）。", -- draft
	-- DungeonInfo
	["Dungeon Info"] = "地下城信息", -- draft
	["Every dungeon and raid: its bosses, what they drop, and your own list of items to watch for."] = "每个地下城和团队副本：首领、掉落以及你自己的心愿物品清单。", -- draft
	["Every dungeon's bosses and their loot beside the map; star the items you want and a loot roll tells you when one drops."] = "地图旁显示每个地下城的首领及其掉落；为想要的物品加星，掉落掷骰时会提醒你。", -- draft
	["Open Dungeon Info"] = "打开地下城信息", -- draft
	["Opens Dungeon Info beside the map. /dungeoninfo opens it too."] = "在地图旁打开地下城信息。/dungeoninfo 也能打开。", -- draft
	["At A Dungeon's Door"] = "在地下城门口", -- draft
	["At a dungeon's door, a row in the widget column with its bosses, your drops there and its quests."] = "在地下城门口，小部件栏中出现一行：其首领、你在那里的掉落和相关任务。", -- draft
	-- HealFlight
	["Heal Effects"] = "治疗效果", -- draft
	["Your heals shown as light flying from your cast bar to the frame of the one you heal."] = "你的治疗化作光芒，从施法条飞向被治疗者的框体。", -- draft
	["Your heals fly from your cast bar to the frame of the one you heal."] = "你的治疗从施法条飞向你治疗对象的框体。", -- draft
	["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans. Quiet: a subtle thread of light."] = "你的治疗外观。按职业：牧师和圣骑士为神圣，德鲁伊为自然，萨满为流水。低调：一缕细光。", -- draft
	["By Class: Holy, Nature or Water"] = "按职业：神圣、自然或水", -- draft
	["Holy: a gold comet"] = "神圣：一颗金色彗星", -- draft
	["Nature: ribbons and leaves"] = "自然：丝带和树叶", -- draft
	["Water: a stream and a splash"] = "水：一道水流和一片水花", -- draft
	["Quiet: a thread of light"] = "低调：一缕细光", -- draft
	["Flying Light"] = "飞行之光", -- draft
	["A light flies from your cast bar to the healed frame. Off: the heal lands at once; the other effects stay."] = "光芒从施法条飞向被治疗的框体。关闭：治疗立即落下；其他效果保留。", -- draft
	["Heal Over Time Ticks"] = "持续治疗跳动", -- draft
	["Each tick of your heals over time plays a small pulse on the frame."] = "你的持续治疗每跳在框体上播放一次小脉冲。", -- draft
	["Buff Landings"] = "增益落下", -- draft
	["A buff landing on your group or your target plays a spiral of light on the frame, in its school's colour (Fortitude, Mark of the Wild, Arcane Intellect, the blessings ...), whoever cast it. A group buff runs out from the caster's frame; in a raid, a small glint. Buffs you can only cast on yourself play nothing."] = "增益落在你的小队或目标身上时，会在框体上播放一道按其法术派系着色的光之螺旋（坚韧、野性印记、奥术智慧、各种祝福……），无论是谁施放的。群体增益从施法者的框体向外传开；在团队中只是一点闪光。只能对自己施放的增益不播放任何效果。", -- draft
	["Plays the chosen heal look once on your own frame."] = "在你自己的框体上播放一次所选治疗外观。", -- draft
