	["Reset %s"] = "重置%s", -- draft
	["Every setting of %s back to its default%s. Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "%s的所有设置恢复默认%s。整个模块的开关和属于你角色的内容保持不变。会先询问。", -- draft
