	["built in"] = "内置", -- draft
	["A profile is a copy of every setting of every module. It leaves out your Dark Mode and what belongs to your characters: the flight points they know, game settings MelloUI borrowed, and steps done once; loading a profile never touches those. The one marked default is applied when MelloUI starts with no settings at all, such as on a fresh install. Load asks before it replaces your settings. Profiles you save here are kept with your settings; Share gives a string to pass one on, and Import as brings one in. The profiles that come with MelloUI are always here."] = "配置是所有模块所有设置的副本。它不包括你的暗色模式以及属于你角色的内容：他们知道的飞行点、MelloUI借用的游戏设置以及只做一次的步骤；载入配置从不触碰这些。标为默认的那个会在MelloUI完全没有设置启动时套用，例如新安装时。载入会在替换你的设置前询问。你在这里保存的配置与设置一起保留；“分享”生成一段字符串用于转交，“导入为”则导入一个。MelloUI自带的配置始终在这里。", -- draft
