	["Profile '%s' imported (%d settings). Load it from the list to use it."] = "配置“%s”已导入（%d项设置）。从列表中载入即可使用。", -- draft
	["No profiles yet. Type a name above and save the current settings."] = "还没有配置。在上方输入名字并保存当前设置。", -- draft
	["Legends"] = "传奇", -- draft
	["Champions"] = "冠军", -- draft
	["MelloUI is free for everyone and always will be. These are the people who help keep it going. Thank you, all of you!"] = "MelloUI 对所有人免费，并且永远免费。这些是帮助它持续发展的人们。谢谢你们每一位！", -- draft
	["No names here yet. They show up with each MelloUI update."] = "这里还没有名字。它们会随每次 MelloUI 更新出现。", -- draft
	["As of %s"] = "截至 %s", -- draft
	["Search options"] = "搜索选项", -- draft
	["Nothing found. Try another word."] = "什么都没找到。换个词试试。", -- draft
	["%d more. Type more letters to narrow it down."] = "还有%d项。多输入几个字缩小范围。", -- draft
	["Top bar"] = "顶部栏", -- draft
	["unlock windows snap snapping auto position positions reset"] = "解锁 窗口 吸附 对齐 自动 位置 重置", -- draft
	["preview simulate simulation test demo try fight combat behave behaviour"] = "预览 模拟 测试 演示 试试 战斗 表现", -- draft
	["Edit Layout"] = "编辑布局", -- draft
	["Move and size MelloUI's windows and bars on the screen itself. Closes the configurator while you edit."] = "直接在屏幕上移动和调整MelloUI的窗口和条。编辑时会关闭配置器。", -- draft
	["See how your interface behaves in a fight, with made-up numbers: resting, the fight, after it. A fight alone or in a group, or one part at a time (the fades, the reminders, the widget column, party frames, the meter, Combat Text, Gains). Out of combat only; Stop ends it."] = "用虚构的数字看看你的界面在战斗中如何表现：休息时、战斗中、战斗后。单人或队伍中的一场战斗，或一次一个部分（淡出、提醒、小部件栏、小队框体、统计、战斗文字、收获）。仅限脱离战斗；“停止”结束。", -- draft
	["Install…"] = "安装…", -- draft
	["The installer: a setup for the whole interface in a few steps, fitted to this screen. Closes the configurator while it runs."] = "安装器：几步完成整个界面的设置，适配此屏幕。运行时会关闭配置器。", -- draft
	-- Core/Installer.lua
	["MelloUI setup"] = "MelloUI 设置向导", -- draft
	["Mello's layout and the window places fitted to this screen. Your other settings stay."] = "Mello的布局和窗口位置适配此屏幕。你的其他设置保持不变。", -- draft
	["MelloUI's settings are still loading; try again in a moment."] = "MelloUI的设置仍在载入；稍后再试。", -- draft
	["Install waits until you are out of combat."] = "安装会等你脱离战斗。", -- draft
	["Close Edit Mode first."] = "请先关闭编辑模式。", -- draft
	["Your screen is still being fitted."] = "你的屏幕仍在适配中。", -- draft
	["Your screen changed; it is being fitted again."] = "你的屏幕变了；正在重新适配。", -- draft
	["Edit Mode already keeps %d account layouts, the most it can. Delete one in Edit Mode, or keep your own layout."] = "编辑模式已保存 %d 个账号布局，已达上限。请在编辑模式中删除一个，或保留你自己的布局。", -- draft
	["Keep or revert the setup you just installed first."] = "请先保留或还原你刚安装的设置。", -- draft
	["There is no setup to go back to."] = "没有可以返回的设置。", -- draft
	["Paused while you are in combat."] = "战斗中已暂停。", -- draft
	["Revert waits until you are out of combat; try again then."] = "还原会等你脱离战斗；届时再试。", -- draft
	["Paused while Edit Mode is open."] = "编辑模式打开时已暂停。", -- draft
	["%s installed. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "已安装%s。保留它，否则计时结束时MelloUI会回到“Before install”。", -- draft
	["Your layout was fitted to this screen. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "你的布局已适配此屏幕。保留它，否则计时结束时MelloUI会回到“Before install”。", -- draft
	["MelloUI's Edit Mode layout did not go in (%s). Your own layout stays; /mello layout check shows why."] = "MelloUI 的编辑模式布局未能应用（%s）。你自己的布局保持不变；/mello layout check 会显示原因。", -- draft
	["the screen was not fitted"] = "屏幕未完成适配", -- draft
	["Back to 'Before install'."] = "已回到“Before install”。", -- draft
	["Something went wrong while installing, so MelloUI went back to 'Before install'."] = "安装时出了问题，所以MelloUI回到了“Before install”。", -- draft
	["Something went wrong while installing. Use Revert to go back to 'Before install'."] = "安装时出了问题。使用“还原”回到“Before install”。", -- draft
	["Something went wrong while preparing the setup. Nothing was changed."] = "准备设置时出了问题。没有任何改动。", -- draft
	["MelloUI could not go all the way back to 'Before install'. Type /reload to try again."] = "MelloUI没能完全回到“Before install”。输入/reload再试一次。", -- draft
	["This setup did not install fully, so it cannot be kept. Revert goes back to 'Before install'."] = "此设置没有完整安装，所以无法保留。“还原”会回到“Before install”。", -- draft
	["MelloUI was only partly put back, so this setup cannot be kept. Revert tries again to go back to 'Before install'."] = "MelloUI只恢复了一部分，所以此设置无法保留。“还原”会再次尝试回到“Before install”。", -- draft
	["%s: %.1f ms in one frame."] = "%s：一帧耗时%.1f毫秒。", -- draft
	["The installer opens when combat ends."] = "战斗结束后打开安装器。", -- draft
	["Close Edit Mode first, then open the installer again."] = "请先关闭编辑模式，然后再次打开安装器。", -- draft
	["Version %s. /mello shows what's new; Install... there sets MelloUI up again."] = "版本%s。/mello显示更新内容；在那里点“安装...”可重新设置MelloUI。", -- draft
	["Use MelloUI's Edit Mode layout on this character too?\n\nYour own layouts stay in Edit Mode's list. Later: /mello layout apply."] = "在这个角色上也使用MelloUI的编辑模式布局吗？\n\n你自己的布局仍保留在编辑模式的列表中。以后可用：/mello layout apply。", -- draft
	["Use it"] = "使用", -- draft
	["MelloUI's Edit Mode layout is not active on this character: pick it in Edit Mode's layout list, or log in without the Gamepad UI to be asked."] = "MelloUI的编辑模式布局在这个角色上未启用：在编辑模式的布局列表中选择它，或不开启手柄界面登录以便被询问。", -- draft
