	["Mello's layout, fitted to this screen, as an account layout of its own, made active. Your own layouts stay in the list, and Revert puts the one you use now back."] = "Mello的布局，适配此屏幕，作为一个独立的账号布局并设为当前。你自己的布局保留在列表中，“还原”会把你现在用的那个放回来。", -- draft
	["Pieces at an edge keep their distance to it; the centre group tightens to fit; then everything is checked for overlaps."] = "靠边的部件保持与边缘的距离；中间的一组收紧以放得下；然后检查所有重叠。", -- draft
