-- stale: ["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "你正在批量制造：第几个、共几个，每件物品一个圆环，悬停时显示停止。", -- draft
-- stale: ["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "背包窗口上腾出栏位的按钮：丢掉价值最低的灰色或白色垃圾物品（在商人处则出售）。绝不丢食物、饮料、药水、卷轴、魔法制造的物品、制造材料、任务物品、施法材料、弹药、钥匙、白色装备或你补货列表上的任何东西。白色物品会先询问。", -- draft
-- stale: ["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "每个队友友方姓名板上方一个职业徽章，带职责颜色的圆环。仅限野外；在副本中游戏不让插件使用友方姓名板。", -- draft
-- stale: ["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "徽章周围按成员指定职责着色的圆环：绿色治疗、蓝色坦克、红色伤害。仅当队伍设置了职责时（队伍查找器会设置；小队可以手动设置）。", -- draft
-- stale: ["A cooldown's icon lights up while you press the action button with its spell, as the button does (Action Buttons)."] = "按下放有该法术的动作按钮时，冷却图标像按钮一样亮起（动作按钮）。", -- draft
-- stale: ["A count going up rolls over to its new number as a soft light runs along its line; a finished objective gets a tick drawn in its dash's place; a finished quest's last count rolls first, then a light runs over its title, its mark turns over to the hand-in ? and its turn-in line comes in. Off: the lines change at once, with their dashes. Not with Reduce Motion."] = "计数增加时翻到新数字，同时一道柔光沿该行划过；完成的目标在短横线处画上对勾；完成的任务先翻动最后一个计数，然后一道光扫过标题，标记翻转为交任务的?，交任务行随之出现。关闭：各行立即改变，保留短横线。“减少动态效果”开启时不会。", -- draft
-- stale: ["A critical or crushing blow on you flashes the bars' rim red and dips them a hair, once."] = "你受到暴击或碾压时，条的边缘闪一次红光并下沉一点点。", -- draft
-- stale: ["A font style is a preset: it changes every font at once. Each card shows its title face and its reading face."] = "字体风格是一个预设：一次改变所有字体。每张卡片显示它的标题字体和阅读字体。", -- draft
-- stale: ["A fresh Mello layout for wide screens, fitted to every other (on 32:9 in the corners); Keep My Layout keeps your places; profiles keep every bar's place and offer Fit to this screen."] = "全新的 Mello 宽屏布局，并适配其他所有屏幕（32:9 时位于角落）；保留我的布局会保留你的位置；配置会保存每个动作条的位置，并提供适配此屏幕。", -- draft
-- stale: ["A fresh Mello layout for wide screens, fitted to every other; Keep My Layout keeps your own places; profiles offer Fit to this screen."] = "全新的宽屏 Mello 布局，并适配其他所有屏幕；“保留我的布局”会保留你自己的位置；配置文件会提供“适配此屏幕”。", -- draft
-- stale: ["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "点击分组按钮时，它的列表像抽屉一样从小地图栏滑出，一行接一行，关闭时滑回去。“减少动态效果”开启时不会：直接显示。", -- draft
-- stale: ["A heal bursts, a heal over time seals onto the portrait, a shield closes round the frame, a resurrection unfolds wings, a group heal runs through the group."] = "治疗迸发，持续治疗封印在头像上，护盾包住框体，复活展开羽翼，群体治疗传遍小队。", -- draft
-- stale: ["A heal lights the health it gives at once; the bar then grows into it."] = "治疗会立即点亮它给予的生命；然后条再长到那里。", -- draft
-- stale: ["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "每件进入背包的物品一行：拾取、任务奖励、制造物品、邮件和交易。在背包、银行和装备之间移动物品从不计入。", -- draft
-- stale: ["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "你获得的其他货币一行（荣誉、徽章、印记），带该货币自己的图标。", -- draft
-- stale: ["A line for what you buy from a merchant, buybacks too, marked as bought."] = "从商人处购买的东西一行（购回也算），标为已购买。", -- draft
-- stale: ["A line not translated yet shows in English. Corrections are welcome on MelloUI's CurseForge translation page."] = "尚未翻译的行显示为英文。欢迎在MelloUI的CurseForge翻译页面上提交更正。", -- draft
-- stale: ["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "你的某项技能提升时显示一行：武器技能、防御、专业、副技能和语言。", -- draft
-- stale: ["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "你的金钱增加时显示一行：拾取、任务奖励、出售、邮件和交易，使用游戏的钱币图标。连续多次收入会合并成一行。花钱不产生行。", -- draft
-- stale: ["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "游戏红色错误信息（“你还不能那么做”）用一声闷响，每半秒最多一次；被“错误信息”隐藏的消息不发声。", -- draft
-- stale: ["A new icon set, sharp at every size, map pins glowing and marks shaded; MelloUI Frames on buttons, XP bars and unit frames; Heal Flight and Frame Effects in soft light."] = "一套新图标，任何尺寸都清晰，地图标记发光，标记带阴影；按钮、经验条和单位框体使用MelloUI框体；治疗效果和框体效果以柔光呈现。", -- draft
-- stale: ["A new installer: skin first, then each part; one setup for every skin, fitted to your screen, reloaded on Keep; moved frames keep their screen edges. Preview: Solo, Party, Raid Fight."] = "全新安装程序：先选外观风格，再逐项设置；所有外观风格同一套设置，按你的屏幕排布，保留时重新载入；移动过的框体会贴住各自的屏幕边缘。预览：单人、小队、团队。", -- draft
-- stale: ["A new installer: your skin first, then each part of the UI step by step, with a picture of every choice."] = "全新安装向导：先选风格，再一步步设置界面各部分，每个选项都有图片。", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, fitted to your screen's shape, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "全新安装程序：先选外观风格，再逐项设置；所有外观风格使用同一套设置，按你的屏幕比例排布，保留时重新载入。预览：单人、小队和团队战斗。", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "全新安装程序：先选外观风格，再逐项设置；所有外观风格使用同一套设置，保留时重新载入。预览：单人、小队和团队战斗。", -- draft
-- stale: ["A new route grows from you to the destination in about a second instead of appearing whole, on the world map and the minimap at once: the beads pop in one after another, the line and the dashes are drawn with a small light at their head, and the destination's flag pops in as the trail reaches it. A re-plan of the same route (you strayed off it) swaps at once. Not with Reduce Motion."] = "新路线用约一秒从你延伸到目的地，而不是整条直接出现，世界地图和小地图同时：珠子一颗颗出现，线和虚线由头部一点小光画出，路线到达时目的地的旗帜出现。同一路线的重新规划（你偏离了路线）立即切换。“减少动态效果”开启时不会。", -- draft
-- stale: ["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "新悄悄话：发送者显示为职业颜色、最后一行以及未读条数。“回复”打开他的悄悄话窗口。需要聊天的“悄悄话弹窗”。", -- draft
-- stale: ["A note under the door for a whisper, two knocks for a group invite."] = "悄悄话是门下塞进的纸条，组队邀请是两声敲门。", -- draft
-- stale: ["A page in the world map's quest log listing the quests of a zone, how many you have completed, and where each one is picked up."] = "世界地图任务日志中的一页，列出一个区域的任务、你完成了多少，以及每个任务在哪里接。", -- draft
-- stale: ["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "拖动法术、宏或技能时纸页掀起，放下时栏位卡住。", -- draft
-- stale: ["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "打开角色面板、法术书、任务日志或主菜单时翻页，关闭时插销声；法术书翻页；任务给予者的列表和拒绝；背包像皮袋一样打开和合上。", -- draft
-- stale: ["A pin into parchment for a minimap ping."] = "微缩地图信号时图钉扎入羊皮纸的声音。", -- draft
-- stale: ["A preset: choosing a style changes every font at once -- the titles, the interface text, the chat and numbers, the chat text and the chat on parchment, the sizes back to 100% (each face brings its own size correction) -- each pairing themed with readability first. Fine-tune any of them afterwards (the style then shows Custom). The damage numbers keep their own choice, but for Fredoka's: one face for everything.\nFredoka: MelloUI's own face: Fredoka's round letters for the titles, the text and the damage numbers, to fit MelloUI's icons. The default.\nScriptorium: Cinzel's carved capitals over Alegreya, a warm book face.\nChronicle: Alegreya SC's small capitals over Source Serif 4, the most readable serif.\nOld Tome: IM Fell English's aged print over Spectral.\nWarband: Pirata One's blackletter over Crimson Pro SemiBold: the boldest look.\nClarity: Cinzel titles, Noto Sans everywhere else: the easiest to read at small sizes.\nGothic: Enchanted Land's gothic titles kept, over Alegreya."] = "预设：选择一种风格会一次改变所有字体——标题、界面文字、聊天和数字、聊天文字和羊皮纸上的聊天，大小恢复到100%（每种字体自带大小校正）——每套搭配都以可读性为先。之后可以微调任意一项（风格随后显示“自定义”）。伤害数字保留自己的选择，Fredoka除外：一种字体用于全部。\nFredoka：MelloUI自己的字体：Fredoka的圆润字母用于标题、文字和伤害数字，与MelloUI的图标相配。默认。\nScriptorium：Cinzel的雕刻大写搭配Alegreya，一种温暖的书籍字体。\nChronicle：Alegreya SC的小型大写搭配Source Serif 4，最易读的衬线体。\nOld Tome：IM Fell English的旧式印刷搭配Spectral。\nWarband：Pirata One的哥特黑体搭配Crimson Pro SemiBold：最醒目的外观。\nClarity：Cinzel标题，其余全部Noto Sans：小字号下最易读。\nGothic：保留Enchanted Land的哥特标题，搭配Alegreya。", -- draft
-- stale: ["A preview of the bar's layout. Changes show after a /reload."] = "条布局的预览。改动在 /reload 后显示。", -- draft
-- stale: ["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "某个专业冷却再次就绪（转化、月布、盐瓶）。打开该专业时MelloUI会记下它。", -- draft
