-- stale: ["A seamless world map of MelloUI's own (M): zoom from Azeroth to a village, ground and caves up close; your party, Route, flights, dungeons, quests and objectives on it."] = "MelloUI自己的无缝世界地图（M）：从艾泽拉斯一直缩放到村庄，近看地面和洞穴；你的队伍、路线、航线、地下城、任务和目标都在上面。", -- draft
-- stale: ["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "每条通知伴随一声短促的提示音：新目的地用地图的追踪音效（世界标记自己的音效播放时省略），到达时一声更柔和的。", -- draft
-- stale: ["A short line when a fight starts and when it ends."] = "战斗开始和结束时一行短文字。", -- draft
-- stale: ["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "用MelloUI外观的射击条和近战条代替游戏的挥击计时条：每次挥击和射击在武器图标旁倒数，副手在主手下方，魔杖射击在近战条上。开启时游戏自己的挥击计时条关闭，关闭时按你原来的设置回来。当个人显示在它的轨道上显示你的挥击时（轨道上的挥击），这些条让开。", -- draft
-- stale: ["A slim beam of light rising from the destination, so the place can be seen from far away, with a small glow on the ground at its foot, red with Red Beads and gold with the other Trail Looks. It fades as you come near and is gone once the marker rises above the place, and hides while the place is off screen. Part of the World Marker."] = "从目的地升起的一道细光柱，远处也能看到该地点，柱脚地面有一小片光晕，红色珠子时为红色，其他路线外观时为金色。靠近时淡出，标记升到地点上方时消失，地点在屏幕外时隐藏。世界标记的一部分。", -- draft
-- stale: ["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "每个团队样式框体或团队框体右侧、生命值旁一个小小的DPS或治疗数字。战斗中MelloUI分辨不出的玩家保持空白，直到战斗结束。指向框体可看三个数字。", -- draft
-- stale: ["A small coloured FPS and latency readout in the bottom right corner."] = "右下角一个小巧的彩色FPS和延迟读数。", -- draft
-- stale: ["A small flag mark over the destination itself, with the distance and the travel time, that stays on it as you move the camera. Far away it is a beacon, smaller the farther the place, faint while it stands in the middle of the screen; within 100 yards it rises above the place, the distance and the name over it and a gold chevron pointing down to it, so it never covers what you are looking for. Inside a quest's objective area it hides, and comes back when you leave. When the place is off screen, an arrow beside your character points the way to turn. Takes the place of the game's own destination marker while it is on."] = "目的地本身上方的一个小旗帜标记，带距离和旅行时间，移动镜头时仍停在那里。远处是一个信标，越远越小，位于屏幕中央时变淡；100码以内时它升到地点上方，距离和名字在上，一个金色V形指向下方，永远不遮住你要找的东西。在任务目标区域内它会隐藏，离开时回来。地点在屏幕外时，角色旁的箭头指示该转向哪边。开启时取代游戏自己的目的地标记。", -- draft
-- stale: ["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "你的背包、银行和公会银行中每件物品左上角的一颗小宝石，颜色为物品品质：垃圾为灰色，普通为白色，然后是绿、蓝、紫和橙。垃圾和更好的物品一眼就能认出。当游戏在那个角显示自己的标记时（商人处的垃圾硬币、升级箭头、开始任务物品上的感叹号、制造材料的品质徽章），宝石会移到右上角。三个窗口一个开关。", -- draft
-- stale: ["A soft breath of air as the World Marker changes: when it comes up for a new destination, as it rises above the place you are near, and as it turns back into the beacon when you walk away. For a new destination it is the one sound: the tracking notice leaves its chime out then. Plays on the Sound Effects channel. Part of the World Marker."] = "世界标记变化时的一声轻柔气息：为新目的地出现时，升到你附近地点的上方时，以及你走开它变回信标时。对新目的地来说这是唯一的音效：此时追踪通知不再响铃。在声音效果频道播放。世界标记的一部分。", -- draft
-- stale: ["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "MelloUI显示在世界上的文字背后加一层柔和暗影，让它在明亮背景上也能看清：进入新区域时的区域名（及其子区域和PvP行）、屏幕中央的游戏消息（红色错误、黄色任务进度、团队警告和首领表情）、路线的世界标记、单位框体上的名字（你的、你宠物的、你目标的目标的和小队的）和姓名板上的名字，以及聊天羊皮纸上的频道标签和链接。区域名和消息不加描边（“描边文字”会加回来）；游戏的颜色保留。关闭：游戏自己的外观，它们背后都没有阴影。", -- draft
-- stale: ["A soft dark shade round the kit's outlines, so windows, bars and frames stand out from the world. Each area has its own switch under it."] = "套件轮廓周围的一层柔和暗影，让窗口、条和框体从世界中凸显出来。每个区域在下方有自己的开关。", -- draft
-- stale: ["A soft glow in the debuff's colour (Magic blue, Curse purple, Disease brown, Poison green) round a friend's frame while they have a debuff that can be removed. On the raid frames the border takes the colour too."] = "友方有可移除的减益时，在其框体周围显示该减益颜色的柔和光晕（魔法蓝、诅咒紫、疾病棕、中毒绿）。团队框体上边框也会变色。", -- draft
-- stale: ["A soft gold glow bursts round your target's bar on a critical hit."] = "暴击时你目标的条周围迸发出柔和的金色光晕。", -- draft
