-- stale: ["How bright the game's own artwork is where Dark mode darkens it. Lower is darker."] = "暗色模式调暗游戏美术处的亮度。越低越暗。", -- draft
-- stale: ["How bright the painted reskin is while Dark Mode is on: every kit piece (stone, iron, plates, brackets) is darkened by this much; the red gems keep their colour. The default art above is darkened where the reskin is off."] = "暗色模式开启时手绘换肤的亮度：每个套件部件（石材、铁、牌匾、支架）按此程度调暗；红宝石保持原色。上方的默认美术在换肤关闭的地方调暗。", -- draft
-- stale: ["How dark the UI Shade round the kit's outlines is, the nameplates' Whole plate shade too. The bands behind unit frame and nameplate names keep their own."] = "套件轮廓周围的界面阴影有多暗，也包括姓名板的“整块牌子”阴影。单位框体和姓名板名字背后的横带保持各自的设置。", -- draft
