-- stale: ["How far from your character the damage and healing lanes run, left and right. Move the whole text in Edit Layout."] = "伤害和治疗分道在左右两侧离你的角色多远。在“编辑布局”中移动整体文字。", -- draft
-- stale: ["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "按钮在小地图下方多远。按钮并入方形小地图边框时不使用。", -- draft
-- stale: ["How fast text-to-speech reads; 0 is the voice's normal pace. Recorded lines always play at their own pace."] = "文字转语音的朗读速度；0为该声音的正常语速。录制的台词始终按自己的语速播放。", -- draft
-- stale: ["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "新提醒在自动收起前停留多久。鼠标指针停在上面时一直保留。", -- draft
-- stale: ["How long an element waits before it fades: after a fight ends, after you let go of your target or point away."] = "元素淡出前等待多久：战斗结束后、你放开目标或移开指针后。", -- draft
-- stale: ["How long an item stays under Recent: until you close your bags, only until you point at it (it moves to its own kind as the pointer leaves it), or for 5 minutes after you got it."] = "物品在“最近”下停留多久：直到你关闭背包，只到你指向它为止（指针离开时移到自己的类别），或获得后5分钟。", -- draft
-- stale: ["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "每行淡出前停留多久。再次获得同一技能或物品会加到它那行并重新计时。", -- draft
-- stale: ["How long the fade itself takes. Coming back is always quick. Reduce Motion: at once."] = "淡出本身需要多久。回来总是很快。减少动态效果：立即。", -- draft
-- stale: ["How long the tooltip of a creature or an object stays fully visible after your cursor leaves it, before it fades out (the fade itself takes a quarter of a second)."] = "光标离开生物或物体后，它的鼠标提示保持完全可见多久再淡出（淡出本身需要四分之一秒）。", -- draft
-- stale: ["How loud text-to-speech reads. Recorded lines follow the Sound Channel's volume in the game's sound settings."] = "文字转语音的音量。录制的台词跟随游戏声音设置中音效频道的音量。", -- draft
-- stale: ["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "一行放几个增益后开始下一行。你的减益另起一行（游戏的减益条每行最多16个）。", -- draft
-- stale: ["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "历史保留多少场战斗，最旧的先删除。/reload后保留；重新登录时清空。", -- draft
-- stale: ["How many frames in a column (or a row) before the next one starts. 5 lines the raid up by its groups."] = "一列（或一行）放多少个框体后开始下一列。5会按小组排列团队。", -- draft
-- stale: ["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "动作条按钮排成几行（如果在编辑模式中竖着放，则为列数）。", -- draft
-- stale: ["How many slots across the bag window is: more makes it wider and shorter."] = "背包窗口横向有多少个栏位：越多越宽越矮。", -- draft
-- stale: ["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "小部件栏同时显示多少个小部件。其余的在顶部一条细细的“+2个”行里等待；点击即列出。拾取掷骰、召唤、复活邀请和就位确认总会显示，Voice Over保留最下方的位置。", -- draft
-- stale: ["How much of an element stays while it is faded. At 0 % it is gone until it is needed (an On Mouseover bar at 0 % still shows when you point at it)."] = "元素淡出时保留多少。在0 %时它会消失，直到需要时才出现（0 %的“鼠标悬停”条在你指向它时仍会显示）。", -- draft
-- stale: ["How names read in chat."] = "聊天中名字的显示方式。", -- draft
-- stale: ["How solid the bars' background is: lower lets the world show through the empty part of a bar."] = "条背景有多实：越低越能透过条的空白部分看到世界。", -- draft
-- stale: ["How solid the chat windows' background is. Moving the Background slider in a chat tab's menu changes this too."] = "聊天窗口背景有多实。在聊天标签菜单中移动“背景”滑块也会改变它。", -- draft
-- stale: ["How solid the painted border round the chat windows and their button column is, and its shade (the painted chat: its Painted Skin, the reskin on)."] = "聊天窗口及其按钮栏周围手绘边框有多实，以及它的阴影（手绘聊天：它的手绘皮肤，换肤开启）。", -- draft
-- stale: ["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "条的高度；副手条为它的60 %，武器圆框从15起随之变大。也可在“编辑布局”中。", -- draft
-- stale: ["How tall the health bar is; the power and cast bars are a little thinner, in step with it. Their frames grow and shrink with them."] = "生命条的高度；能量条和施法条稍细，随之变化。它们的边框也随之缩放。", -- draft
-- stale: ["How tall the square map is (the round map takes its Width). The shorter side is at least half the longer one."] = "方形地图的高度（圆形地图取其宽度）。短边至少为长边的一半。", -- draft
-- stale: ["How tall the tracker may grow before it scrolls (at least 88, room for the title and a few lines). Edit Mode's: the height set for the game's tracker in Edit Mode. The grip in its bottom-left corner sets it by dragging."] = "追踪器开始滚动前最多能长多高（至少88，够放标题和几行）。“编辑模式的”：编辑模式中为游戏追踪器设置的高度。拖动左下角的把手即可设置。", -- draft
-- stale: ["How the chat is shown. Game Windows: the game's chat windows and tabs. Minimal: one panel with a rail of round tabs on its left (one per chat window, a count of the lines you have not seen; Whispers last), each line under its sender's name, channel and time, and a row of round buttons under the lines: Say, Party, Raid, Instance, Guild, Yell, Whisper and Emote open the line you type in on that chat, then Channels, Friends, the fight history and these settings. A whisper puts a count on the Whispers tab and shows the Whispers widget; either opens one whisper window above the chat with every conversation in it, theirs left and yours right. Parchment (its own switch) puts both on the parchment sheet."] = "聊天的显示方式。游戏窗口：游戏的聊天窗口和标签。极简：一个面板，左侧是一排圆形标签（每个聊天窗口一个，显示你未看的行数；悄悄话在最后），每行在发送者名字、频道和时间下方，各行下面是一排圆形按钮：说、小队、团队、副本、公会、大喊、悄悄话和表情会打开对应聊天的输入行，然后是频道、好友、战斗历史和这些设置。一条悄悄话会在悄悄话标签上显示计数并显示悄悄话小部件；任一项都会在聊天上方打开一个包含所有对话的悄悄话窗口，对方的在左，你的在右。羊皮纸（它自己的开关）把两者都铺到羊皮纸上。", -- draft
-- stale: ["How the parchment looks wherever it shows: the sheets switched on below, and the quest log, quest and spell book pages. Burnt paper: warm paper with burnt edges, big pages with curled corners. Classic vellum: the vellum with painted brush-stroke edges from before 0.20.1."] = "羊皮纸在各处的样子：下方开启的纸张，以及任务日志、任务和法术书页面。焦纸：带焦边的暖色纸，大页面有卷角。经典牛皮纸：0.20.1之前带手绘笔触边缘的牛皮纸。", -- draft
-- stale: ["How the raid's frames are grouped: by raid group (1 to 8), by role, by class, or one list."] = "团队框体的分组方式：按团队小组（1到8）、按职责、按职业，或一个列表。", -- draft
-- stale: ["How the route is drawn on the world map and the minimap: red beads in gold rings, one pale gold line, or short pale gold dashes. The destination is a flag in a gold ring either way."] = "路线在世界地图和小地图上的画法：金环中的红色珠子、一条淡金线，或淡金色短虚线。目的地无论如何都是金环中的旗帜。", -- draft
-- stale: ["How the value is written."] = "数值的写法。", -- draft
-- stale: ["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "你在竞速条线上的份额有多粗（标记和标签保持大小）。也可在“编辑布局”中：右键竞速条。", -- draft
-- stale: ["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "条的宽度；武器圆框挂在左边，秒数在右边。也可在“编辑布局”中（在那里右键一条）。", -- draft
-- stale: ["How wide the health, power and cast bars are. Edit Layout sizes the whole display."] = "生命条、能量条和施法条的宽度。“编辑布局”调整整个显示的大小。", -- draft
-- stale: ["How wide the map is. The round map is as tall as it is wide, and its painted ring grows and shrinks with it. The square map's border and the zone name keep their size, the Services buttons too (smaller only on a map too narrow for them), and the Quest Tracker under the map follows its width. Edit Mode's minimap Size no longer sizes the map while the Minimap Kit is on."] = "地图的宽度。圆形地图高宽相等，手绘圆环随之缩放。方形地图的边框和区域名保持大小，服务按钮也是（仅在地图太窄放不下时变小），地图下方的任务追踪器跟随其宽度。小地图套件开启时，编辑模式的小地图大小不再决定地图大小。", -- draft
-- stale: ["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "竞速条的宽度。也可在“编辑布局”中：右键竞速条。", -- draft
-- stale: ["How wide the tracker is when it does not match the minimap's width (at least 60). Edit Mode's: as wide as the game's tracker. The grip in its bottom-left corner sets width and height by dragging (only the height while it matches the minimap)."] = "不与小地图同宽时追踪器的宽度（至少60）。“编辑模式的”：与游戏追踪器同宽。拖动左下角的把手可设置宽度和高度（与小地图同宽时只能设置高度）。", -- draft
-- stale: ["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans (Holy for anyone else). Water: water circles your cast bar, a winding stream throws off droplets, a splash lands; a shield is a water bubble, a heal to full a geyser. Holy: gold sparks spiral into your spell's icon, a gold comet flies, a white flash and a burst of rays land, rune marks linger round the frame. Nature: green and gold ribbons circle your cast bar, ribbons fly shedding leaves, leaves burst and rise. Quiet: your cast bar's fill glows, a thin thread of light flies, the frame's border flares. Each kind lands its own way in each look: a heal over time sinks in, a shield wraps the frame in a barrier, protection puts a crest over it, a heal to full raises a column of light, a resurrection lights the fallen one's frame."] = "你的治疗看起来的样子。按职业：牧师和圣骑士为神圣，德鲁伊为自然，萨满为水（其他职业为神圣）。水：水流环绕你的施法条，一道蜿蜒的水流甩出水滴，落下一片水花；护盾是一个水泡，满血治疗是一道间歇泉。神圣：金色火花螺旋汇入你的法术图标，一颗金色彗星飞出，落下白色闪光和一束光芒，符文印记在框体周围停留。自然：绿金丝带环绕你的施法条，丝带一路洒落树叶飞去，树叶迸开升起。低调：施法条的填充发光，一缕细光飞出，框体边框亮起。每种类型在每种外观中都有自己的落点：持续治疗渗入，护盾用屏障包住框体，保护在其上放一个纹章，满血治疗升起一道光柱，复活点亮倒下之人的框体。", -- draft
-- stale: ["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "重要技能、效能技能和增益效果冷却查看器的图标框和条背景。", -- draft
-- stale: ["Icons stay smooth and sharp at every size and UI scale: each one is drawn from a copy made for its size on your screen."] = "图标在任何大小和缩放下都平滑清晰：每个图标都由按其屏幕尺寸制作的副本绘制。", -- draft
-- stale: ["In Combat elements come back while you have a target, a friend too."] = "“战斗中”的元素在你有目标时回来，友方目标也算。", -- draft
-- stale: ["In Combat elements come back while you point at them, too. (On Mouseover elements always do.)"] = "“战斗中”的元素在你指向它们时也会回来。（“鼠标悬停”的元素总是如此。）", -- draft
-- stale: ["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "战斗中：条在战斗中一挥击或射击就显示，战斗结束时淡出（射击条在自动射击停止时也会）。总是：携带相应武器时每条都显示，挥击间隙保持静止。", -- draft
-- stale: ["In a fight"] = "战斗中", -- draft
-- stale: ["In a fight the widget shrinks to the speaker's face and its ring, and the reading goes on (a book too). The name and the line come back when the fight is over."] = "战斗中小部件缩小为说话者的脸和圆环，朗读继续（书本也是）。战斗结束后名字和台词回来。", -- draft
-- stale: ["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "战斗中为队伍显示一条线：最高的玩家在右端并带数值，其他人是位于其占最高者比例处的职业图标，你是较大的图标，线用你的职业颜色填到你的位置。战斗开始时淡入，结束时淡出。指针放在上面会列出所有人。可在“编辑布局”中移动。", -- draft
-- stale: ["In a group fight, a thin bar along the bottom of an enemy's health bar (in the Nameplate Kit's lower rail) fills to the point where it would turn on you: gold while safe, amber when close, red when it is on you. For a tank it turns red when a mob is not on you. Solo it stays away."] = "在队伍战斗中，敌人生命条底部（姓名板套件的下石条里）一条细条，填充到它会转向你的位置：安全时为金色，接近时为琥珀色，在你身上时为红色。对坦克来说，怪不在自己身上时变红。单人时不显示。", -- draft
-- stale: ["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "在队伍战斗中，只在要紧时显示：快要从坦克那里拉走目标（“收着点”）或目标已在你身上（“OT”），坦克则显示没有打你的怪。圆环是你相对OT阈值的仇恨；指向它可看全队对你目标的仇恨。", -- draft
-- stale: ["In a party: these frames, or MelloUI's normal party frames (the game's party frames with their portraits, in the painted look). With the normal ones, you show as one of them while solo too (Show Yourself While Solo), so you can see your heals and indicators on it. In a raid these frames show. The normal party frames show as the game's Edit Mode sets them: with Raid-Style Party Frames on there, the game shows none of its normal ones."] = "在小队中：这些框体，或MelloUI的普通小队框体（游戏的带头像小队框体，手绘外观）。使用普通框体时，你单人时也作为其中之一显示（单人时显示自己），这样可以在上面看到你的治疗和指示器。在团队中显示这些框体。普通小队框体按游戏编辑模式的设置显示：如果那里开启了团队样式小队框体，游戏不显示任何普通框体。", -- draft
-- stale: ["In a party: these frames, or the classic party frames with portraits. In a raid, these frames always show."] = "在小队中：这些框体，或带头像的经典小队框体。在团队中总是显示这些框体。", -- draft
-- stale: ["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "在任务目标区域且背包里有任务物品时：物品、一个表示目标进度的圆环以及你携带的数量。点击使用物品（脱离战斗时：战斗中会收起）。", -- draft
-- stale: ["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "在旅店或城市里，以及哨兵岭这样的城镇里，每个提醒都保留到完成为止（打开了邮箱、学会了法术或等级……）或你离开；在那里点“现在不”会等到你下次进入。", -- draft
-- stale: ["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "以银币计：价值达到或超过此数的一组物品绝不会被丢掉（在商人处出售仍可）。100银币 = 1金币。", -- draft
-- stale: ["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "在拆分堆叠的框里（Shift+点击一个堆叠），鼠标滚轮改变数量：向上加一，向下减一，按住Shift时一次十个。", -- draft
