-- stale: ["Into a fight the bars rise into place; a moment after it they settle a little lower, until the next one. (To fade them out of combat: the Fader.)"] = "进入战斗时条升到位；战斗结束片刻后稍微下沉，直到下一场。（脱离战斗时淡出它们：用淡出功能。）", -- draft
