-- stale: ["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "让小部件栏（Voice Over、拾取掷骰、跑尸及其他）保持原位：“编辑布局”会显示它的牌子但不移动它。Voice Over的锁也会设置这一项。", -- draft
-- stale: ["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "让你的背包里常备饮料、食物、弹药和施法材料：某项不足时提醒你（需开启提醒），到了商店列出要买的东西，只在你点击“购买”时才买。", -- draft
-- stale: ["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "保留游戏在可拾取任务物品上的闪光。它需要关闭游戏的轮廓模式，而图形预设会重新打开它：开启时保持关闭，关闭时按你原来的设置还原。关闭此项后闪光会在下次重启游戏后消失（客户端重启；/reload不够）。", -- draft
-- stale: ["Languages: the configurator and the installer in German, French, Spanish, Portuguese, Russian, Chinese and Korean. Pick one at the left of the top line."] = "语言：配置器和安装器提供德语、法语、西班牙语、葡萄牙语、俄语、中文和韩语。在顶部一行的左侧选择。", -- draft
