-- stale: ["Read a book, letter, note, plaque or sign aloud when you open it: the whole book, from the page you open to the last, with no page turning, and it goes on when you close it or walk away. Turning a page reads on from that page; Stop ends it. The narrator's recordings come from the voice pack (MelloUI_VoicePack); without it only the page you see is read, with text-to-speech when Read Unvoiced Lines is on."] = "打开书、信、便条、牌匾或告示时朗读：整本书，从打开的那页读到最后一页，无需翻页，关闭或走开后仍继续。翻页会从那一页继续读；“停止”结束朗读。旁白的录音来自语音包（MelloUI_VoicePack）；没有它时只读你看到的那页，开启“朗读无配音的台词”时用文字转语音。", -- draft
-- stale: ["Read a quest or greeting the voice pack has no recording of with a text-to-speech voice. Off: only recorded lines are heard and the rest stay silent."] = "语音包没有录音的任务或问候用文字转语音的声音朗读。关闭：只能听到录制的台词，其余保持安静。", -- draft
-- stale: ["Read lines one after another: a greeting finishes before the quest offer that follows it. Off makes every new dialog interrupt the previous one."] = "一行接一行地朗读：问候读完后才读接下来的任务提供。关闭时每个新对话都会打断上一个。", -- draft
-- stale: ["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "5秒以内为红色且更大（文字大小的1.3倍），一分钟以内为黄色，以分钟计为暗白且更小（0.8倍），以小时计为灰色且再小一些（0.75倍）。关闭：所有计时均为白色，使用文字大小。", -- draft
-- stale: ["Remember where you walk and fly so routes can follow real roads. What it learns is saved and kept from one session to the next. /route shows how much has been learned."] = "记住你走过和飞过的地方，让路线沿真实的道路走。学到的内容会保存，跨游戏会话保留。/route显示已学了多少。", -- draft
