-- stale: ["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "当武器上的毒药、油或磨刀石用完或只剩两分钟，而你身上带着可以补上的时，提醒你。一直保留到补上为止（战斗中也是）；点击即可补上（脱离战斗时）。", -- draft
