-- stale: ["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "当你自己的某个增益不在你身上时提醒你：奥术智慧和法师的护甲、坚韧、心灵之火和神圣之灵、野性印记、术士的护甲。只限你能施放的增益。一直保留到增益回来为止（战斗中也是；游戏在战斗中隐藏增益，所以战斗中失去的会在战斗后显示）；点击施放（脱离战斗时）。", -- draft
-- stale: ["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "当队伍中有人缺少你能施放的增益时提醒你（奥术智慧和神圣之灵只针对使用法力的人）；指向它可看到他们的名字。一直保留到他们都有为止（战斗中也是）；点击逐个为他们施放（脱离战斗时）。", -- draft
-- stale: ["Remind you when you have talent points to spend."] = "有天赋点可用时提醒你。", -- draft
