-- stale: ["The bag window's money rolls to its new sum when it changes (selling, buying, a repair, a quest) instead of jumping there: warm while it goes up, red while it goes down. Not with Reduce Motion."] = "背包窗口的金钱变化时（出售、购买、修理、任务）滚动到新数额而不是直接跳过去：增加时为暖色，减少时为红色。“减少动态效果”开启时不会。", -- draft
-- stale: ["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "按上面几行排布的动作条。松开滑块时存入你的编辑模式布局（战斗中则在战斗结束时）；动作条本身在重载后改变。", -- draft
-- stale: ["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "下面几行设置的动作条：它的行数、图标、图标大小和间距，在你松开滑块时（脱离战斗）按编辑模式的方式存入你当前的编辑模式布局。游戏在重载后显示它们：输入/reload（MelloUI会提示一次）。会先复制游戏的一个预设布局：只询问一次。", -- draft
-- stale: ["The bars glide to a new value instead of jumping."] = "条平滑过渡到新数值，而不是跳变。", -- draft
-- stale: ["The bars of your experience and the reputation you watch. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "你的经验条和关注的声望条。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
-- stale: ["The bars under your character and the shield column beside it (Personal Display). In Combat, they also come back while you cast. (No On Mouseover: the pointer passes through them to the world.) Always: never faded. In Combat: faded out of combat, back in a fight."] = "你角色下方的条和旁边的护盾栏（个人显示）。“战斗中”时，你施法时它们也会回来。（没有“鼠标悬停”：指针会穿过它们点到世界。）总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。", -- draft
-- stale: ["The border of the backdrop round the action bars (and the experience and reputation bars): the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "动作条（以及经验条和声望条）周围底板的边框：角上的红色或铁色宝石，或Oldschool > 边框中的一种边框样式（画得较粗，内角斜切）。每个元素的底板在“条”中开启（它的底板）；放在一起的已开启元素共用一个底板，外观取第一个：动作条1、其他条、微型菜单、背包栏。", -- draft
-- stale: ["The border of the backdrop round the bag bar: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "背包栏周围底板的边框：角上的红色或铁色宝石，或Oldschool > 边框中的一种边框样式（画得较粗，内角斜切）。每个元素的底板在“条”中开启（它的底板）；放在一起的已开启元素共用一个底板，外观取第一个：动作条1、其他条、微型菜单、背包栏。", -- draft
-- stale: ["The border of the backdrop round the micro menu: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "微型菜单周围底板的边框：角上的红色或铁色宝石，或Oldschool > 边框中的一种边框样式（画得较粗，内角斜切）。每个元素的底板在“条”中开启（它的底板）；放在一起的已开启元素共用一个底板，外观取第一个：动作条1、其他条、微型菜单、背包栏。", -- draft
-- stale: ["The border on each raid frame and raid-style party frame: the Single rail they wear today, one of the thin rims the buttons wear, or the Backdrop, its corner gems in the colour of the action bars' Backdrop."] = "每个团队框体和团队样式小队框体的边框：现在使用的单石条、按钮使用的一种细边，或底板（角上的宝石为动作条底板的颜色）。", -- draft
-- stale: ["The border round the square map: the windows' frame with its gem corners, a single iron rail, the action bars' heavy frame with red or iron gems, one of the thin rims the buttons wear (drawn heavier, at the map's size), or none. Picked with pictures on the Minimap page, its Border part. The painted borders need the painted Minimap skin (Oldschool); without it the map wears the Chat panel."] = "方形地图周围的边框：带宝石角的窗口边框、单铁条、带红色或铁色宝石的动作条粗边框、按钮使用的一种细边（按地图尺寸画得更粗），或无。在小地图页面的“边框”部分用图片选择。手绘边框需要手绘小地图皮肤（Oldschool）；没有它时地图使用聊天面板。", -- draft
-- stale: ["The buffs you give yourself on a cooldown -- Shield Wall, Shield Block, Last Stand, Evasion, Ice Block, Recklessness, a trinket's -- as icons above the health bar, their time sweeping round them and their seconds on them, the most important first: an immunity, then damage taken down, more health, block, evasion, the rest. From the game's own spell data, for every class."] = "你给自己施加的带冷却的增益——盾墙、盾牌格挡、破釜沉舟、闪避、寒冰屏障、鲁莽、饰品的——以图标显示在生命条上方，时间绕着它们转，秒数在上面，最重要的在前：免疫，然后减伤、更多生命、格挡、闪避、其他。取自游戏的法术数据，适用于所有职业。", -- draft
-- stale: ["The character window on a parchment sheet, its text in dark ink: Right pane lays it under the right pane (the stats, reputation, skills and the other lists); Whole window over the whole window inside its frame, the window's own stone round its edge. Off: no parchment; the window shows its Window Background (Windows > Character window)."] = "角色窗口铺在羊皮纸上，文字为深色墨水：“右侧窗格”将其铺在右侧窗格下（属性、声望、技能和其他列表）；“整个窗口”铺满边框内的整个窗口，窗口自己的石材围在边缘。关闭：没有羊皮纸；窗口显示它的窗口背景（窗口 > 角色窗口）。", -- draft
-- stale: ["The chat and whisper windows' text on their parchment sheet, relative to the chat's own size."] = "羊皮纸上聊天和悄悄话窗口的文字，相对于聊天自己的大小。", -- draft
-- stale: ["The chat input box shows only while you type: Enter (or /) brings it up, and it goes again once you send the line or press Escape. It sets the game's Chat Style to Classic while on, and gives your own back when off. The change shows from the next line you type."] = "聊天输入框只在你打字时显示：按回车（或/）调出，发送这一行或按Esc后消失。开启时把游戏的聊天风格设为经典，关闭时恢复你自己的设置。从你输入的下一行开始生效。", -- draft
-- stale: ["The chat on a parchment sheet, its text in dark ink: the Minimal Chat View and its whisper window with the reskin on or off; the game's chat windows with the painted chat (its Painted Skin, the reskin on)."] = "聊天铺在羊皮纸上，文字为深色墨水：极简聊天视图及其悄悄话窗口，换肤开启或关闭均可；游戏的聊天窗口配合手绘聊天（它的手绘皮肤，换肤开启）。", -- draft
-- stale: ["The chat windows (on top of the game's own chat font size) and every number."] = "聊天窗口（在游戏自己的聊天字体大小之上）和所有数字。", -- draft
-- stale: ["The chat windows and whisper windows while they lie on their parchment sheet (Oldschool > Parchment). By default the chat text's face in its semibold cut where it has one, heavier so the dark ink reads on the paper; each Font Style sets that cut of its reading face."] = "聊天窗口和悄悄话窗口铺在羊皮纸上时（Oldschool > 羊皮纸）。默认使用聊天文字字体的半粗体（如果有），更粗，让深色墨水在纸上易读；每种字体风格都会设置其阅读字体的这个字重。", -- draft
-- stale: ["The chat windows with their tabs, buttons, the Friends button and the line you type in. They come back while you type. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "聊天窗口及其标签、按钮、好友按钮和输入行。你打字时它们会回来。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
-- stale: ["The chat windows' background: a dark panel of the palette behind the window, its tabs and its input box (Dark), the game's own (Game), or none at all (None). Under the painted chat (its Painted Skin, the reskin on) its stone instead. With the Minimal Chat View: None leaves its panel clear, Dark and Game keep its dark panel; Parchment lays the parchment sheet over it."] = "聊天窗口的背景：窗口、标签和输入框后面的配色深色面板（深色），游戏自己的（游戏），或完全没有（无）。在手绘聊天下（它的手绘皮肤，换肤开启）改用它的石材。使用极简聊天视图时：无让它的面板透明，深色和游戏保留它的深色面板；羊皮纸在上面铺一张羊皮纸。", -- draft
-- stale: ["The chat windows' messages, the chat's input box and the whisper windows. The same face as the Interface text unless you choose otherwise (the Chat & numbers face while that is the game's), so the chat follows the Font Styles and your own choice of reading face. The size stays the chat's own (Chat & numbers size)."] = "聊天窗口的消息、聊天输入框和悄悄话窗口。默认与“界面文字”相同，除非你另选（当“聊天和数字”为游戏字体时用它），这样聊天会跟随字体风格和你自己选择的阅读字体。大小仍是聊天自己的（“聊天和数字”大小）。", -- draft
-- stale: ["The chosen health bar colour wins over the game's own recolouring of health bars (the aggro / threat display on nameplates and unit frames): whenever the game sets its colour, yours is put back. Off: the game's threat colours show."] = "所选的生命条颜色胜过游戏自己对生命条的重新着色（姓名板和单位框体上的仇恨 / 威胁显示）：每当游戏设置它的颜色，你的颜色就会被放回去。关闭：显示游戏的仇恨颜色。", -- draft
-- stale: ["The colour behind the health bar with My Colour."] = "选择“我的颜色”时生命条后面的颜色。", -- draft
-- stale: ["The colour behind the health bar: one of yours, or the member's class colour."] = "生命条后面的颜色：你的一种颜色，或该成员的职业颜色。", -- draft
-- stale: ["The colours of all the painted art (frames, headers, rows, buttons, slots, bars). With the Ember and Ember Vibrant palettes: Warm iron (the metal in warm browns), Bronze (warm browns with gold bevels), or the Original painted grey iron and bright red. With any other palette: that palette's own colours, or the Original. Pictures keep their own colours."] = "所有手绘美术的颜色（边框、标题、行、按钮、栏位、条）。使用 Ember 和 Ember Vibrant 配色时：暖铁（暖棕色的金属）、青铜（带金色斜边的暖棕色），或原版手绘灰铁加亮红。使用其他配色时：该配色自己的颜色，或原版。图片保留自己的颜色。", -- draft
-- stale: ["The column of widgets: loot rolls, summons, Voice Over, whispers and the rest. A new one does not bring the column back: In Combat keeps a loot roll, a summons or a whisper faded out of combat, On Mouseover until you point at the column. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "小部件栏：拾取掷骰、召唤、Voice Over、悄悄话等。新的小部件不会让栏回来：“战斗中”让拾取掷骰、召唤或悄悄话在脱离战斗时保持淡出，“鼠标悬停”直到你指向这一栏。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
-- stale: ["The configurator's frame previews stand on the left with room around them; the settings sit beside them."] = "配置器的框体预览位于左侧，四周留有空间；设置在旁边。", -- draft
