-- stale: ["The display keeps its place by your character as you zoom the camera: closer under your feet when you zoom out, further down when you zoom in, so it never covers your character. Place it in Edit Layout at the zoom you play at; it follows from there. Turning the camera up or down is not followed (the game does not tell)."] = "缩放镜头时显示保持在角色旁：拉远时更靠近脚下，拉近时更往下，永远不遮住你的角色。在“编辑布局”中按你常用的缩放放置；之后会自动跟随。镜头上下转动不跟随（游戏不提供）。", -- draft
-- stale: ["The experience and reputation bars in MelloUI's look: a slim iron frame with gold diamond ends, a dark track, the notches between the bar's parts and a soft light on the filling edge. Off: the game's own frame. The painted skin's bars keep their own (Oldschool)."] = "MelloUI外观的经验条和声望条：细铁框配金色菱形端头、深色轨道、条分段之间的刻痕以及填充边缘的柔光。关闭：游戏自己的框。手绘皮肤的条保留自己的（Oldschool）。", -- draft
