-- stale: ["The numbers over the enemies: the game's own (after /reload) and Your Damage's (at once); and the hit numbers on the unit frames' portraits. The game's text around you (Combat Text's Game style) and MelloUI's are drawn in the Interface text face."] = "敌人头上的数字：游戏自己的（/reload后）和“你的伤害”的（立即）；以及单位框体头像上的伤害数字。你周围的游戏文字（战斗文字的“游戏”风格）和MelloUI的文字使用“界面文字”字体绘制。", -- draft
-- stale: ["The numbers: cooldown counts, stack counts; and the chat windows while Chat text and Interface text both keep the game's. The value text on the unit frames' bars follows the Interface text, the hit numbers on the portraits the Game Numbers Font."] = "数字：冷却计数、堆叠数；以及当“聊天文字”和“界面文字”都保留游戏字体时的聊天窗口。单位框体条上的数值文字跟随“界面文字”，头像上的伤害数字跟随“游戏数字字体”。", -- draft
