-- stale: ["The party frames, the game's and the raid-style ones. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "小队框体，游戏的和团队样式的。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
-- stale: ["The player, target, focus, target of target, pet and party frames in MelloUI's look, exactly as the game lays them out: a gold ring round the portrait, a dark level badge, and gold-lined iron borders round the name, health and power; the elite's and boss's golden dragon and the rare's silver one round the target. Off: the game's own frame art. The painted skin's frames keep their own (Oldschool)."] = "MelloUI外观的玩家、目标、焦点、目标的目标、宠物和小队框体，完全按游戏的布局：头像周围一圈金环、深色等级徽章，名字、生命和能量周围带金线的铁边框；目标周围有精英和首领的金龙、稀有的银龙。关闭：游戏自己的框体美术。手绘皮肤的框体保留自己的（Oldschool）。", -- draft
