-- stale: ["The rim round your buffs and debuffs, the target's and the nameplates' (Buffs & Debuffs): a plain black edge or one of the thin rims the buttons wear. The debuff colour stays round the icon. Only MelloUI's own aura rows wear it (Buffs & Debuffs, off by default): the game's own buff and debuff icons keep their edge, which Dark Mode's Buffs & Debuffs darkens."] = "你的增益和减益效果、目标的和姓名板的（增益和减益效果）的边缘：朴素黑边或按钮使用的一种细边。减益颜色保留在图标周围。只有MelloUI自己的光环行使用它（增益和减益效果，默认关闭）：游戏自己的增益和减益图标保留它们的边缘，由暗色模式的“增益和减益效果”调暗。", -- draft
-- stale: ["The ring round the portraits of the unit frames: the player, target, focus, pet, target of target and party. The gem ring, a ring with four diamond studs, a plain heavy ring, or the winged border the windows wear. An elite, rare or boss shows the ring in its metal with its crest (Elite and Rare Marks)."] = "单位框体头像周围的圆环：玩家、目标、焦点、宠物、目标的目标和小队。宝石环、带四颗菱形钉的环、朴素粗环，或窗口使用的翼状边框。精英、稀有或首领会以其金属色和纹章显示圆环（精英和稀有标记）。", -- draft
