-- stale: ["The round reminders beside your portrait (restock, mail, your buffs, the weapon's poison...). A new reminder does not bring them back: In Combat keeps it faded until a fight, On Mouseover until you point at them. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "头像旁的圆形提醒（补货、邮件、你的增益、武器毒药……）。新提醒不会让它们回来：“战斗中”保持淡出直到战斗，“鼠标悬停”直到你指向它们。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
