-- stale: ["What lies behind the health and power bars, under the fill, the heals coming in and the bars' borders: the painted dark trough, a flat dark, the Bar Texture's finish in the dark, or nothing. Every unit frame: the player, target, focus, pet, target of target and party."] = "生命条和能量条后面、填充、预计治疗和条边框下方的东西：手绘深色凹槽、纯深色、深色中的条材质质感，或无。所有单位框体：玩家、目标、焦点、宠物、目标的目标和小队。", -- draft
-- stale: ["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "生命条后面的东西：纯色（背景颜色）、MelloUI的背景之一（石材、水泥、羊皮纸、深色渐变……），或无。", -- draft
