-- stale: ["What the bag windows show behind the items (Bags by Kind's window too, and the bank): cracked concrete (the window's own), stone, iron plate, parchment, leather or dark."] = "背包窗口在物品后面显示的东西（背包分类窗口和银行也是）：裂纹水泥（窗口自己的）、石材、铁板、羊皮纸、皮革或深色。", -- draft
-- stale: ["What the character window shows behind everything: its own stone, or stone, cracked concrete, iron plate, leather or dark. Parchment is Oldschool > Parchment's Character Window: under the right pane, or over the whole window (on its own stone, whatever this shows). The equipment slots, the progress bars and the side tabs wear the borders of Oldschool > Borders (every window's)."] = "角色窗口在一切后面显示的东西：它自己的石材，或石材、裂纹水泥、铁板、皮革或深色。羊皮纸属于Oldschool > 羊皮纸的“角色窗口”：铺在右侧窗格下，或整个窗口上（在它自己的石材上，无论这里显示什么）。装备栏位、进度条和侧边标签使用Oldschool > 边框中的边框（每个窗口通用）。", -- draft
-- stale: ["What the crafting page shows behind the recipe list and the recipe: cracked concrete, stone, iron plate, parchment, leather or dark."] = "制造页在配方列表和配方后面显示的东西：裂纹水泥、石材、铁板、羊皮纸、皮革或深色。", -- draft
-- stale: ["What the professions' book page shows behind the profession cards: cracked concrete, stone, iron plate, parchment, leather or dark. The spells' rims wear the Button Border, the rank bars the Progress Bar Border (Oldschool > Borders)."] = "专业书页在专业卡片后面显示的东西：裂纹水泥、石材、铁板、羊皮纸、皮革或深色。法术边缘使用按钮边框，等级条使用进度条边框（Oldschool > 边框）。", -- draft
-- stale: ["What the race bar races. Auto: healing while your group role is healer, else damage."] = "竞速条比拼的内容。自动：你的队伍职责为治疗者时比治疗，否则比伤害。", -- draft
-- stale: ["What the recipe list shows behind its rows: its darker list stone, or one of the other backgrounds. All three are chosen with pictures on Windows > Professions. The reagent slots wear the Button Border, the rank bar the Progress Bar Border, the finished item the Round Border (Oldschool > Borders, every window's)."] = "配方列表在各行后面显示的东西：它自己更深的列表石材，或其他背景之一。三项都在窗口 > 专业中用图片选择。材料栏位使用按钮边框，等级条使用进度条边框，成品使用圆形边框（Oldschool > 边框，每个窗口通用）。", -- draft
-- stale: ["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "背包里要常备什么、多少。每个角色有自己的列表；新列表从该职业的建议开始。也可用/restock。", -- draft
-- stale: ["When an NPC's greeting text was changed but the pack has exactly one recorded greeting for that NPC, play the recording anyway instead of reading the new text aloud. The words will not match what is on screen."] = "当某个NPC的问候文字改变了，但语音包里恰好有该NPC的一条录制问候时，仍然播放录音而不是朗读新文字。说的话会和屏幕上的不一致。", -- draft
-- stale: ["When an action's cooldown runs out, a golden light runs once round its button, so you see it is ready again. Never for the global cooldown."] = "动作冷却结束时，一道金光绕按钮跑一圈，让你看到它又就绪了。公共冷却从不触发。", -- draft
-- stale: ["When an item comes into your bag window or leaves it, the others glide to their new slots instead of jumping there; one that moves to the next row slides in at its start, and a new one fades in. Switching between the Backpack and the Reagent Bag fades the window's items over. Not while you hold an item (its + slots come and go at once), not with Reduce Motion."] = "物品进入或离开背包窗口时，其他物品滑到新栏位而不是跳过去；移到下一行的物品从行首滑入，新物品淡入。在行囊和材料包之间切换时窗口的物品淡入淡出。拿着物品时不会（它的+栏位即时出现消失），“减少动态效果”开启时也不会。", -- draft
-- stale: ["When no map pin is set, route to the quest you are tracking (the one with the arrow): to the nearest place for an objective you have not finished yet (a creature to kill, an object to use, where the item drops or is sold, a place to explore), and to its turn-in once it is complete. An objective that needs an item in your bags first (remains to bury, a key for a cage) is routed to where that item comes from until you have it."] = "没有设置地图标记时，规划前往你追踪的任务（带箭头的那个）的路线：前往尚未完成的目标的最近地点（要击杀的生物、要使用的物体、物品掉落或出售的地方、要探索的地点），完成后前往交任务处。需要先在背包中有某件物品的目标（要埋葬的遗骸、笼子的钥匙），在你拿到之前路线指向那件物品的来源。", -- draft
-- stale: ["When nothing is super-tracked, follow the first quest on the game's watch list instead of showing nothing. That is the game's own order of the quests you watch, not the Quest Tracker's Nearest Quest First order."] = "没有超级追踪时，跟随游戏追踪列表中的第一个任务，而不是什么都不显示。这是游戏自己对你追踪任务的顺序，不是任务追踪器“最近的任务在前”的顺序。", -- draft
-- stale: ["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "当你的某个专业可以在训练师处学习下一级时：中级、高级或专家级。", -- draft
-- stale: ["When something does not fit because your bags are full, the bag window's Empty slot (it shows 0 then) gives one short shake and a red flash; with the bags closed, the backpack button flashes red. Once each time, as the game's own \"Inventory is full.\" line comes. Not with Reduce Motion."] = "因背包已满放不下东西时，背包窗口的“空”栏位（此时显示0）短促地晃一下并闪红；背包关闭时行囊按钮闪红。每次游戏出现“物品栏已满。”这一行时一次。“减少动态效果”开启时不会。", -- draft
-- stale: ["When the World Marker comes up for a new destination, a small light flies from your character to the place and lights it: the beam rises and the mark pops in as it lands. It follows the place as you turn the camera; while the place is off the screen it settles into the arrow beside your character. Firefly: a bright point with a short streak. Embers: a smaller glow shedding sparks. Not with Reduce Motion. Part of the World Marker."] = "世界标记为新目的地出现时，一点小光从你的角色飞到该地点并点亮它：光柱升起，标记在它落下时出现。转动镜头时它跟随地点；地点在屏幕外时它停在角色旁的箭头里。萤火虫：一个亮点带一小段拖尾。余烬：较小的光晕洒落火花。“减少动态效果”开启时不会。世界标记的一部分。", -- draft
-- stale: ["When you enter a dungeon or raid, list in chat the quests for it you could have picked up but have not."] = "进入地下城或团队副本时，在聊天中列出你本可以接但没接的该副本任务。", -- draft
-- stale: ["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "升级时，一道光沿经验条划过，屏幕通知告诉你新等级，配合任务列表还会告诉你它在你所在区域开放了多少任务（下次世界地图显示时任务给予者会出现在上面）。使用手绘换肤时，玩家框体等级圆圈里的数字也会伴着一圈光翻转。“减少动态效果”开启时不会：只有通知。", -- draft
-- stale: ["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "获得经验时，经验条上刚获得的那一段会亮起，同时一道光划向新的末端。“减少动态效果”开启时不会。", -- draft
-- stale: ["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "当你达到职业训练师有新法术的等级时。一直保留到你学会它们；每次拜访职业训练师都会告诉MelloUI下一批何时到来，第一次拜访之前则按训练师授课的等级判断。", -- draft
-- stale: ["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "你给队伍当坦克时，在两波怪之间：队伍中的治疗者正在喝水，所以下一波之前等一等。治疗者停下或战斗开始时消失。游戏对插件隐藏队友的法力值，所以这里显示的是他在喝水，而不是他的法力。", -- draft
-- stale: ["When your target dodges, parries or is missed, the word flicks off the side of its plate."] = "你的目标躲闪、招架或你未命中时，字样从它姓名板的侧边弹出。", -- draft
-- stale: ["Where Raid Frame Border goes: on each raid frame, round each raid group, or both. A group's border shows while Edit Mode's Display Border is on for the raid frames."] = "团队框体边框的位置：每个团队框体上、每个团队小组周围，或两者都有。当编辑模式中团队框体的“显示边框”开启时，小组的边框才会显示。", -- draft
-- stale: ["Where the next row of buffs goes: under the first, or over it."] = "下一行增益放在哪里：第一行下方或上方。", -- draft
-- stale: ["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "提醒按钮在你头像旁的位置。玩家框体隐藏时它有自己的位置，可在“编辑布局”中移动。", -- draft
-- stale: ["Where the text sits on the bar."] = "文字在条上的位置。", -- draft
-- stale: ["Which"] = "哪些", -- draft
-- stale: ["Which debuffs light a frame: every one that can be removed, the ones someone in your group can remove, or only the ones you can remove."] = "哪些减益会点亮框体：所有可移除的、队伍中有人能移除的，或只有你能移除的。", -- draft
