-- stale: ["Which way your icons run under the player frame: from the bars' left end rightwards, or from their right end leftwards."] = "玩家框体下方图标排列的方向：从条的左端向右，或从右端向左。", -- draft
-- stale: ["Which windows wear the painted kit."] = "哪些窗口穿上手绘套件。", -- draft
-- stale: ["While a heal over time of yours runs (Renew, Rejuvenation, Regrowth's), each of its ticks plays a small pulse on the frame: a ring and three motes (Holy), a leaf (Nature), a drop and a ripple (Water), the border's breath (Quiet, and in a raid). Timed from the game's spell data: Renew ticks five times in 15 seconds."] = "你的持续治疗生效期间（恢复、回春术、愈合的持续部分），每跳都会在框体上播放一个小脉动：一个环和三颗光点（神圣）、一片叶子（自然）、一滴水和一圈涟漪（水）、边框的呼吸（低调，以及团队中）。时机取自游戏的法术数据：恢复在15秒内跳五次。", -- draft
-- stale: ["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "背包栏隐藏时，在打开的背包窗口下方显示背包栏位，这样仍能装上和取下背包。开启或关闭“合并背包”选项都可用。", -- draft
-- stale: ["While the objective marks are on, the game's own blue quest areas and quest markers on the world map are switched off, through the game's own Quest Objectives setting (the quest buttons in the game's quest tracker go with it). Turning this or the marks off gives the game's setting back as you had it."] = "目标标记开启时，通过游戏自己的“任务目标”设置关闭世界地图上游戏的蓝色任务区域和任务标记（游戏任务追踪器中的任务按钮也随之消失）。关闭此项或标记时，游戏的设置按你原来的样子恢复。", -- draft
-- stale: ["While you are not in a group, your own frame stands where your party's will, with your indicators on it. Move it in Edit Layout. With In A Party set to Party Frames, it is a normal party frame where the game's party frames stand (move those in Edit Mode)."] = "不在队伍中时，你自己的框体位于小队框体将出现的位置，上面带有你的指示器。可在“编辑布局”中移动。“在小队中”设为小队框体时，它是位于游戏小队框体位置的普通小队框体（在编辑模式中移动它们）。", -- draft
-- stale: ["While you are stunned, feared, silenced or locked out of a school, the bars' rim turns red and a line under them runs down its time, its name under it. The game's own banner over your character is off while this is on, and comes back as you had it when it is off."] = "你被昏迷、恐惧、沉默或某个学派被锁定时，条的边缘变红，下方一条线倒数时间，名字在下面。开启时游戏在角色上方的横幅关闭，关闭时按你原来的设置回来。", -- draft
-- stale: ["While you hold an action button's key, or press it with the mouse, the whole button lights up in the colour scheme's highlight colour, so you can see which button you are pressing."] = "按住动作按钮的按键或用鼠标按下时，整个按钮以配色方案的高亮色亮起，让你看到正在按哪个按钮。", -- draft
-- stale: ["While you hold an item, every kind in your bag window shows a + slot: drop the item there and it always goes under that kind (drop it on its own kind's + to put it back). Forget puts every item you placed back under its own kind."] = "手里拿着物品时，背包窗口的每个类别都显示一个+栏位：把物品放到那里，它就总归在那个类别下（放到它自己类别的+上即可放回）。“忘记”把你放置的每件物品放回它自己的类别。", -- draft
-- stale: ["Who draws the text over your character. Game: the game's own, as it always was. Lanes: damage taken falls on your left, healing rises on your right, procs and Dodge / Parry above your head, resources under your feet. Feed: one column over your portrait, the newest on top. Classic: one stream over your head, like the game's, in MelloUI's font and soft shade."] = "由谁绘制你角色上方的文字。游戏：游戏自己的，一如既往。分道：受到的伤害落在你左侧，治疗从右侧升起，触发和躲闪 / 招架在头顶，资源在脚下。信息流：头像上方一列，最新的在最上面。经典：头顶一道文字流，和游戏的一样，但使用MelloUI的字体和柔和阴影。", -- draft
-- stale: ["Who shows a power bar (mana, rage, energy) under their health."] = "谁在生命条下方显示能量条（法力、怒气、能量）。", -- draft
-- stale: ["Whose big moments play on the frames. Yours: when you use one (Challenging Shout, Shield Wall, Last Stand, Divine Shield, Evasion ...), your own frame in your party or raid frames plays its effect for as long as it lasts (a roar: 2 seconds). Your group's: when someone of your party or raid uses one, their frame plays it -- you see at a glance who just used Shield Wall or Divine Shield, and whose roar just pulled."] = "框体上播放谁的高光时刻。你的：当你使用时（挑战怒吼、盾墙、破釜沉舟、圣盾术、闪避……），小队或团队框体中你自己的框体在其持续期间播放效果（怒吼：2秒）。你队伍的：当你的小队或团队中有人使用时，他的框体播放它——一眼就能看出谁刚开了盾墙或圣盾术，谁的怒吼刚拉了怪。", -- draft
-- stale: ["Whose nameplate gets the class medallion above the name."] = "谁的姓名板在名字上方显示职业徽章。", -- draft
-- stale: ["Window text, buttons, tooltips, the quest log, nameplate names and the names above characters in the world (those after /reload)."] = "窗口文字、按钮、鼠标提示、任务日志、姓名板名字以及世界中角色头顶的名字（这些在/reload后）。", -- draft
-- stale: ["Window titles, quest and item names in dialogs, mail and book text, and the kit's title plates and headers while the reskin is on. Enchanted Land unless you choose otherwise. Keep the game's leaves each string in the game's own face: Morpheus where the game uses it, the interface face on the strings that start in it (the Quest Tracker's headers, Combat Text's notices)."] = "窗口标题、对话中的任务和物品名称、邮件和书籍文字，以及换肤开启时套件的标题牌匾和题头。默认Enchanted Land，除非你另选。“保留游戏的”让每段文字使用游戏自己的字体：游戏使用Morpheus的地方用Morpheus，原本用界面字体的文字用界面字体（任务追踪器的标题、战斗文字的通知）。", -- draft
-- stale: ["Windows framed in gold, snapped ones sharing one rim; the widget column's rows on gold cards, in motion; new class portraits; the Personal Display in gold and in motion."] = "窗口加上金框，吸附的窗口共用一个边框；小部件栏的行置于金色卡片上并有动效；新的职业头像；个人显示采用金色并有动效。", -- draft
-- stale: ["With Heal Effects on (Frame Effects > Heals): the light of a heal you cast gathers at your character's middle instead of on the cast bar, and flies from there to the party or raid frame of the one you heal. It follows the display's place and the camera's zoom."] = "开启治疗效果时（框体效果 > 治疗）：你施放的治疗之光在角色身体中间汇聚，而不是在施法条上，然后从那里飞向你治疗对象的小队或团队框体。它跟随显示的位置和镜头缩放。", -- draft
-- stale: ["With a choice of rewards: take the one with the highest item level over what you wear in its slot, among those you can use; when none is better, the one that sells for the most."] = "有奖励可选时：在你能用的奖励中，选物品等级比你该栏位所穿装备高出最多的；都不更好时，选卖价最高的。", -- draft
-- stale: ["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "把这些行写进聊天，而不是显示在屏幕上。即使“聊天通知”关闭，它们也会显示在那里。", -- draft
-- stale: ["X / Y"] = "X / Y", -- draft
-- stale: ["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "当一行低于其数量的这个比例时提醒你：在50 %时，一行20瓶水会在剩9瓶时提醒。在商店里会补回完整数量。提醒需要开启提醒；补货列表无论如何都会标出不足的行。", -- draft
-- stale: ["Your UI and bars stay. MelloUI's features switch on."] = "你的界面和动作条保持不变。开启MelloUI的功能。", -- draft
-- stale: ["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "你的插件的小地图按钮（Questie以及其他在小地图边缘放圆形按钮的插件）从小地图上拿下来，收进服务栏中额外的一个分组“插件”：点击它即可看到列表。在那里点击插件就是点击插件本身（左键、右键或中键），指向它会显示它自己的鼠标提示。仅限按钮布局为“分组”时。关闭：按钮回到小地图上。", -- draft
-- stale: ["Your aura indicators on the frames. Off: the frames show none."] = "框体上你的光环指示器。关闭：框体不显示任何指示器。", -- draft
-- stale: ["Your bag window's kinds in the order they show, the top first: drag a row to move it. A line draws a line across the window between the kinds over and under it; a group puts the kinds under it, to the next line, under one heading you can fold. Untick a kind and its items go to their own type, or to Other. Add kind makes one of your own: it takes the items you drop on its + slot and the ones its rule matches (an item type, a word in the name, a quality), before the game's kinds. Double-click a name to rename it; a kind's cog opens its settings: its name, Split By Type (a heading for each item type, in its place) and an own kind's rule."] = "你背包窗口的类别，按显示顺序，最上面的在前：拖动一行即可移动它。“分隔线”在上下类别之间画一条横贯窗口的线；“分组”把它下面直到下一条线的类别收在一个可折叠的标题下。取消勾选一个类别，它的物品会归到自己的类型，或归到“其他”。“添加类别”新建你自己的类别：它会收下你拖到它+栏位上的物品，以及符合它规则（物品类型、名称中的词、品质）的物品，优先于游戏的类别。双击名字可重命名；类别的齿轮打开它的设置：名字、“按类型拆分”（在原位为每种物品类型加一个标题）以及自定义类别的规则。", -- draft
-- stale: ["Your bags in one window of MelloUI's own, sorted by kind: what you picked up lately, gear, quest items, consumables, junk, trade goods and the rest, each under its own heading. The empty slots fold into one slot with their count."] = "你的背包在MelloUI自己的一个窗口中，按类别排序：最近拾取的、装备、任务物品、消耗品、垃圾、商品等，各在自己的标题下。空栏位折叠成一个带数量的栏位。", -- draft
-- stale: ["Your bags' buttons. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "你的背包按钮。总是：从不淡出。战斗中：脱离战斗时淡出，战斗时回来。鼠标悬停：一直淡出，指向时显示。", -- draft
-- stale: ["Your bank in the same kinds as your bags, inside the game's bank window: its items under their headings, the lines and groups of the Kinds list, the empty slots folded into one, a + slot in every kind while you hold an item. Deposit and take out as always (right-click, drag). Off: the game's own grid."] = "你的银行按与背包相同的类别显示，在游戏的银行窗口内：物品在各自标题下，类别列表的分隔线和分组，空栏位折叠成一个，拿着物品时每个类别都有+栏位。照常存取（右键、拖动）。关闭：游戏自己的网格。", -- draft
-- stale: ["Your buffs in a line beside the minimap, level with the map's top and growing away from it, your debuffs on the line under them. They follow the minimap when it moves or changes size. Needs the Minimap Kit; off, they stand where the game's buff bar is."] = "你的增益在小地图旁排成一行，与地图顶端齐平并向远离地图的方向增长，减益在下一行。小地图移动或改变大小时跟随它。需要小地图套件；关闭时它们位于游戏增益栏的位置。", -- draft
-- stale: ["Your buffs, then your debuffs on a row of their own. Right-click a buff to cancel it. Beside the minimap, or where the game's buff bar is: that bar comes back while Edit Mode is open, so it can still be moved, and these follow it."] = "你的增益，然后减益另起一行。右键增益可取消它。在小地图旁或游戏增益栏的位置：编辑模式打开时那个栏会回来，仍可移动，这些行跟随它。", -- draft
