-- stale: ["Your swing timer without a bar of its own: in a fight, two sparks run out from the middle of the health bar's top rail to its ends, and your swing lands as they reach them. An off hand's swings run along the bottom of the power bar. Your shots run on the seam between the health and power bars: cream sparks out while you reload, then a red line grows back from the ends while you aim (stand still: moving holds it), and the shot flies as it meets in the middle. A wand's shots run out once, with no aim. While it is on, MelloUI's Swing Timers step aside and the game's own swing timers stay off."] = "没有独立条的挥击计时：战斗中，两颗火花从生命条上沿轨道的中间奔向两端，到达时你的挥击落下。副手挥击沿能量条底部奔跑。你的射击沿生命条和能量条之间的接缝奔跑：装填时奶油色火花向外跑，然后瞄准时一条红线从两端向回生长（站着别动：移动会拖住它），在中间会合时射击飞出。魔杖射击向外跑一次，不用瞄准。开启时MelloUI的挥击计时条让开，游戏自己的挥击计时条保持关闭。", -- draft
